for _w in ("tanjung", "sabana", "warung", "bemo", "ojek", "bukit", "danau", "kain", "tenun", "pasar"):
    SRC["kbbi_" + _w] = ["KBBI daring: " + _w, "https://kbbi.web.id/" + _w]

TERMS = []
def term(slug, name, rx, see, src, en, es, id, aka=None, pron=None, nolink=()):
    """name: str or {lang: str}; rx: regex (str or {lang: str}) that finds the term in our texts; see: item slugs listed first;
    en/es/id: (definition, explanation with paragraphs separated by newlines); nolink: languages where the word is too ordinary to link."""
    TERMS.append({"slug": slug, "name": name if isinstance(name, dict) else {"en": name, "es": name, "id": name}, "rx": rx if isinstance(rx, dict) else {"en": rx, "es": rx, "id": rx},
                  "see": see, "src": [SRC[k] for k in src], "aka": aka or [], "pron": pron, "nolink": nolink,
                  "def": {"en": en[0], "es": es[0], "id": id[0]}, "body": {"en": en[1], "es": es[1], "id": id[1]}})

term("marapu", "Marapu", r"marapu", ["marapu-ikat-traditional-villages", "sumba-weddings-funerals-ceremonies", "pasola-explained"], ["arch"],
 en=("Marapu is the ancestral religion of Sumba, in which the ancestors remain present among the living and are honoured with offerings and ceremonies. It guides planting, marriage, funerals and the settling of disputes, and it is the belief behind the Pasola, the stone tombs and the tall clan houses. Most Sumbanese are Christian today, but Marapu remains central to ceremonies and identity.",
 """In Marapu the dead join the ancestors, who in turn bless or punish the living. That is why funerals are the largest and most carefully staged events in Sumbanese life, and why a family may wait a long time to bury a relative properly. Rocks, trees and springs can be home to spirits, and each stage of important work, from planting to weaving a cloth, is opened with prayers.
The belief is visible in the architecture. In the traditional house the space under the roof peak is reserved for the ancestors and for sacred heirlooms, the family lives in the middle and animals are kept below. Ritual life is led by the Rato, the customary elders, who also set the dates of the Pasola.
How many people follow Marapu depends on who counts. Official religious statistics for 2023 put Marapu and other faiths at a little over 3% of the island, while other estimates run from about a quarter to more than a third, strongest in the traditional villages of the west and centre. Many families who are Christian still keep Marapu rites.
For visitors the practical meaning is simple: villages are homes with sacred places, not museums. Ask before entering and before taking photos, and never touch graves or ritual objects."""),
 es=("Marapu es la religión ancestral de Sumba: los antepasados siguen presentes entre los vivos y se les honra con ofrendas y ceremonias. Orienta la siembra, el matrimonio, los funerales y la resolución de conflictos, y es la creencia que hay detrás de la Pasola, las tumbas de piedra y las altas casas de clan. Hoy la mayoría de los sumbaneses son cristianos, pero el marapu sigue en el centro de las ceremonias y de la identidad de la isla.",
 """En la creencia marapu los muertos se unen a los antepasados, que a su vez bendicen o castigan a los vivos. Por eso los funerales son los actos más grandes y mejor preparados de la vida sumbanesa, y por eso una familia puede esperar mucho tiempo hasta enterrar a un pariente como es debido. Las rocas, los árboles y los manantiales pueden albergar espíritus, y cada etapa de un trabajo importante, de la siembra al tejido de una tela, se abre con oraciones.
La creencia se ve en la arquitectura. En la casa tradicional, el espacio bajo la cumbre del tejado se reserva a los antepasados y a las reliquias sagradas; la familia vive en el nivel intermedio y los animales, debajo. La vida ritual la dirigen los rato, los ancianos de la costumbre, que también fijan las fechas de la Pasola.
Cuánta gente sigue el marapu depende de quién cuente. Las estadísticas oficiales de 2023 atribuyen al marapu y a otras creencias algo más del 3 % de la población, mientras que otras estimaciones van de una cuarta parte a más de un tercio, sobre todo en los pueblos tradicionales del oeste y el centro. Muchas familias cristianas conservan ritos marapu.
Para quien visita la isla, la consecuencia práctica es sencilla: los pueblos son hogares con lugares sagrados, no museos. Hay que pedir permiso antes de entrar y de hacer fotos, y no tocar nunca las tumbas ni los objetos rituales."""),
 id=("Marapu adalah kepercayaan leluhur orang Sumba: para leluhur diyakini tetap hadir di tengah orang hidup dan dihormati dengan persembahan serta upacara. Kepercayaan ini menuntun masa tanam, perkawinan, pemakaman, dan penyelesaian sengketa, serta melatari Pasola, kubur batu, dan rumah adat bermenara. Kini sebagian besar orang Sumba beragama Kristen, tetapi Marapu tetap menjadi inti upacara dan jati diri pulau ini.",
 """Dalam kepercayaan Marapu, orang yang meninggal bergabung dengan para leluhur, dan leluhur itulah yang memberkati atau menghukum orang hidup. Karena itu pemakaman menjadi peristiwa terbesar dan paling teliti dipersiapkan dalam kehidupan orang Sumba, dan sebuah keluarga bisa menunggu lama sebelum menguburkan kerabatnya dengan layak. Batu, pohon, dan mata air dapat menjadi tempat roh, dan setiap tahap pekerjaan penting, dari menanam hingga menenun kain, dibuka dengan doa.
Kepercayaan ini tampak pada arsitektur. Di rumah adat, ruang di bawah puncak atap disediakan bagi leluhur dan benda pusaka, keluarga tinggal di bagian tengah, dan ternak dipelihara di kolong. Kehidupan ritual dipimpin para Rato, tetua adat yang juga menetapkan tanggal Pasola.
Jumlah penganut Marapu bergantung pada siapa yang menghitung. Statistik agama resmi tahun 2023 mencatat Marapu dan kepercayaan lain sedikit di atas 3 persen penduduk, sedangkan perkiraan lain berkisar dari seperempat hingga lebih dari sepertiga, terutama di kampung adat di bagian barat dan tengah. Banyak keluarga Kristen masih menjalankan ritus Marapu.
Bagi pengunjung, artinya sederhana: kampung adalah rumah dengan tempat-tempat keramat, bukan museum. Mintalah izin sebelum masuk dan sebelum memotret, dan jangan pernah menyentuh kubur atau benda ritual."""))

term("pasola", "Pasola", r"pasola", ["pasola-explained", "pasola-2027-dates", "sumba-horses-sandalwood-pony"], ["detik"],
 en=("The Pasola is a ritual of western Sumba in which two teams of horsemen charge across an open field and throw wooden spears at each other. It is held every year in February in Kodi and Lamboya and in March in Wanokaka and Gaura, on days set by the Rato elders. It belongs to the Marapu ritual year and marks the start of the planting season; it is a ceremony, not a show.",
 """There is no fixed calendar date. The Rato read the phases of the moon and signs in nature, and the decisive one is the arrival of the nyale sea worms on the shore. The Pasola can only take place once the worms have been gathered, so the exact days are usually confirmed only a few weeks ahead. The month before is a sacred period with taboos for the local community, and in West Sumba the Pasola is preceded by pajura, a traditional boxing ritual held at night or before dawn.
Riders gallop on small, fast Sandalwood ponies. Older accounts say that blood spilled on the field fed the land; today the spears are blunt, but riders still fall and horses run where they want. The Indonesian news site detikBali traces the name to a local word for a wooden lance, hola.
For visitors: there is usually no ticket. Dress modestly, stay well back from the field, ask before photographing people and go with a local guide or driver who knows where and when to be. In 2026 police in West Sumba banned alcohol and the carrying of sharp weapons during the pajura and the Pasola."""),
 es=("La Pasola es un ritual del oeste de Sumba en el que dos grupos de jinetes cargan a campo abierto y se lanzan jabalinas de madera. Se celebra cada año en febrero en Kodi y Lamboya y en marzo en Wanokaka y Gaura, en los días que fijan los ancianos rato. Forma parte del año ritual marapu y marca el comienzo de la siembra: es una ceremonia, no un espectáculo.",
 """No tiene fecha fija en el calendario. Los rato leen las fases de la luna y las señales de la naturaleza, y la decisiva es la llegada a la orilla de los nyale, unos gusanos marinos. La Pasola solo puede celebrarse cuando se han recogido los gusanos, de modo que los días exactos suelen confirmarse con pocas semanas de antelación. El mes anterior es un periodo sagrado con tabúes para la comunidad, y en Sumba Occidental la precede el pajura, un combate ritual a puñetazos que se celebra de noche o antes del amanecer.
Los jinetes galopan sobre ponis sandalwood, pequeños y veloces. Los relatos antiguos dicen que la sangre derramada en el campo alimentaba la tierra; hoy las jabalinas no tienen punta, pero los jinetes siguen cayendo y los caballos corren hacia donde quieren. El diario digital detikBali relaciona el nombre con una palabra local para la lanza de madera, hola.
Para quien la visita: por lo general no hay entrada. Conviene vestir con discreción, mantenerse bien lejos del campo, pedir permiso antes de fotografiar a la gente e ir con un guía o conductor local que sepa dónde y cuándo estar. En 2026 la policía de Sumba Occidental prohibió el alcohol y llevar armas blancas durante el pajura y la Pasola."""),
 id=("Pasola adalah ritual di Sumba bagian barat: dua kelompok penunggang kuda saling menyerbu di lapangan terbuka sambil melempar lembing kayu. Pasola digelar setiap tahun pada Februari di Kodi dan Lamboya serta pada Maret di Wanokaka dan Gaura, pada hari yang ditetapkan para Rato. Ritual ini bagian dari tahun adat Marapu dan menandai awal musim tanam; ini upacara, bukan tontonan.",
 """Tidak ada tanggal tetap di kalender. Para Rato membaca fase bulan dan tanda-tanda alam, dan penentunya adalah munculnya nyale, cacing laut, di pantai. Pasola baru bisa digelar setelah nyale didapat, sehingga hari pastinya biasanya baru dipastikan beberapa minggu sebelumnya. Sebulan sebelumnya adalah masa keramat dengan sejumlah pantangan bagi warga, dan di Sumba Barat Pasola didahului pajura, tinju adat yang berlangsung malam hari atau menjelang subuh.
Para penunggang memacu kuda sandel yang kecil dan gesit. Catatan lama menyebut darah yang tertumpah di lapangan menyuburkan tanah; kini lembingnya tumpul, tetapi penunggang tetap bisa jatuh dan kuda berlari ke mana saja. Menurut detikBali, nama pasola berasal dari kata setempat untuk lembing kayu, hola.
Bagi pengunjung: biasanya tidak ada tiket. Berpakaianlah sopan, berdirilah jauh dari lapangan, mintalah izin sebelum memotret orang, dan datanglah bersama pemandu atau sopir setempat yang tahu tempat dan waktunya. Pada 2026 polisi di Sumba Barat melarang minuman keras dan membawa senjata tajam selama pajura dan Pasola."""))

term("rato", "Rato", r"\brato\b", ["pasola-2027-dates", "pasola-explained", "tarung-village"], ["detik", "gnfi"],
 en=("A Rato is a customary elder and ritual leader of the Marapu faith in Sumba. The Rato read the moon and the signs of nature, set the dates of the Pasola and of the sacred month of Wulla Poddu, and lead the ceremonies that go with them. Their decisions are the reason these dates are never fixed far in advance.",
 """Visitors meet the word most often in one sentence: the dates are set by the Rato. For the Pasola, the elders follow the phases of the moon and wait for the nyale sea worms to appear on the shore; plump, healthy worms are read as the promise of a good harvest, and only then can the riders take the field. The days are usually confirmed a few weeks ahead, in some years only a week or two, and in Southwest Sumba the announcement tends to come in late January.
The same authority opens Wulla Poddu, the sacred month observed around Waikabubak in roughly October and November. According to the West Sumba government, as quoted by Good News From Indonesia, the month begins with a meeting of two elders, the Rato Rumata, who fix the starting date. In Tarung, some houses hold the responsibility for deciding when the month begins.
What this means in practice: do not book flights around a rumoured date. Check our Pasola calendar, ask your accommodation or driver shortly before travelling, and accept that the final word belongs to the elders. During ritual periods some places are closed to outsiders, so go with a local guide and follow instructions."""),
 es=("Un rato es un anciano de la costumbre y jefe ritual de la religión marapu en Sumba. Los rato leen la luna y las señales de la naturaleza, fijan las fechas de la Pasola y del mes sagrado de Wulla Poddu y dirigen las ceremonias que las acompañan. Sus decisiones explican por qué esas fechas nunca se conocen con mucha antelación.",
 """El viajero se encuentra la palabra casi siempre en la misma frase: las fechas las fijan los rato. Para la Pasola, los ancianos siguen las fases de la luna y esperan a que los gusanos marinos nyale aparezcan en la orilla; si llegan gordos y sanos se interpreta como promesa de buena cosecha, y solo entonces pueden salir los jinetes al campo. Los días suelen confirmarse con pocas semanas de margen, algunos años con solo una o dos, y en Sumba Suroccidental el anuncio suele llegar a finales de enero.
La misma autoridad abre el Wulla Poddu, el mes sagrado que se guarda en torno a Waikabubak hacia octubre y noviembre. Según el gobierno de Sumba Occidental, citado por Good News From Indonesia, el mes comienza con una reunión de dos ancianos, los Rato Rumata, que fijan la fecha de inicio. En Tarung, algunas casas tienen la responsabilidad de decidir cuándo empieza.
En la práctica: no conviene reservar vuelos según una fecha que circula como rumor. Lo sensato es consultar nuestro calendario de la Pasola, preguntar al alojamiento o al conductor poco antes de viajar y aceptar que la última palabra es de los ancianos. Durante los periodos rituales algunos lugares se cierran a los forasteros, así que hay que ir con un guía local y seguir sus indicaciones."""),
 id=("Rato adalah tetua adat sekaligus pemimpin ritual kepercayaan Marapu di Sumba. Para Rato membaca bulan dan tanda-tanda alam, menetapkan tanggal Pasola dan bulan suci Wulla Poddu, serta memimpin upacara yang menyertainya. Keputusan merekalah yang membuat tanggal-tanggal itu tidak pernah pasti jauh hari.",
 """Pengunjung paling sering menjumpai kata ini dalam satu kalimat: tanggalnya ditetapkan para Rato. Untuk Pasola, para tetua mengikuti fase bulan dan menunggu nyale, cacing laut, muncul di pantai. Nyale yang gemuk dan sehat dibaca sebagai pertanda panen baik, dan baru setelah itu para penunggang turun ke lapangan. Harinya biasanya dipastikan beberapa minggu sebelumnya, pada tahun tertentu hanya satu atau dua minggu, dan di Sumba Barat Daya pengumumannya kerap keluar pada akhir Januari.
Wewenang yang sama membuka Wulla Poddu, bulan suci yang dijalani di sekitar Waikabubak kira-kira pada Oktober dan November. Menurut Pemerintah Kabupaten Sumba Barat, seperti dikutip Good News From Indonesia, bulan itu dimulai dengan pertemuan dua tetua, Rato Rumata, untuk menentukan tanggal awal. Di Tarung, beberapa rumah bertanggung jawab memutuskan kapan bulan itu dimulai.
Artinya dalam praktik: jangan memesan tiket pesawat berdasarkan tanggal kabar burung. Periksa kalender Pasola kami, tanyakan kepada penginapan atau sopir menjelang berangkat, dan terimalah bahwa keputusan akhir ada pada para tetua. Selama masa ritual sebagian tempat tertutup bagi orang luar, jadi datanglah bersama pemandu setempat dan ikuti arahannya."""))

term("ikat", {"en": "Ikat", "es": "Ikat", "id": "Tenun ikat"}, {"en": r"\bikat\b", "es": r"\bikat\b", "id": r"tenun ikat"}, ["sumba-ikat-weaving-where-to-buy", "marapu-ikat-traditional-villages", "prailiu-village"], ["kbbi_tenun", "textiles"], pron="EE-kaht",
 en=("Ikat is cloth whose pattern is tied and dyed into the threads before they are woven. The word comes from the Indonesian mengikat, to tie. Sumba's cloth is warp ikat, traditionally dyed with indigo for blue and morinda root for red, and a large natural-dye piece can take from about four months to a year to make.",
 """The work starts long before the loom. Bundles of warp threads are bound tightly where the dye must not reach, dipped, dried, untied and bound again for the next colour. Only then does the weaver, usually a woman working on a backstrap loom, pass the weft through. Indigo gives blue and morinda root gives red; yellow comes from kayu kuning wood or turmeric. The Indonesian dictionary KBBI lists tenun ikat as a weaving technique found in Nusa Tenggara.
East Sumba, around Waingapu, Kambera, Melolo, Rende and Kaliuda, is the home of the large figurative cloths that collectors mean when they say Sumba ikat. Motifs include horses, deer, crocodiles, the skull tree and the mamuli ornament. On this island the cloth is still made for funerals and weddings, not only for visitors: fine pieces are exchanged as counter-gifts for bridewealth and wrapped around the dead.
When buying, ask whether a cloth is natural or synthetic dye; both are honest products if labelled honestly. In 2025-2026 small chemical-dye pieces cost roughly Rp 250,000, while a large hand-spun, natural-dye hinggi runs from about Rp 1.5 million to well over Rp 10 million. Buy directly from the weavers when you can."""),
 es=("El ikat es un tejido cuyo dibujo se ata y se tiñe en los hilos antes de tejerlos. La palabra viene del indonesio mengikat, atar. El de Sumba es ikat de urdimbre, teñido tradicionalmente con índigo para el azul y raíz de morinda para el rojo, y una pieza grande con tintes naturales puede llevar de unos cuatro meses a un año de trabajo.",
 """El trabajo empieza mucho antes del telar. Los haces de hilos de urdimbre se atan con fuerza allí donde el tinte no debe llegar; se sumergen, se secan, se desatan y se vuelven a atar para el siguiente color. Solo entonces la tejedora, casi siempre una mujer con un telar de cintura, pasa la trama. El índigo da el azul y la raíz de morinda, el rojo; el amarillo sale de la madera de kayu kuning o de la cúrcuma. El diccionario indonesio KBBI recoge tenun ikat como una técnica de tejido propia de Nusa Tenggara.
Sumba Oriental, en torno a Waingapu, Kambera, Melolo, Rende y Kaliuda, es la cuna de las grandes telas figurativas a las que se refieren los coleccionistas cuando hablan de ikat de Sumba. Entre los motivos hay caballos, ciervos, cocodrilos, el árbol de los cráneos y el adorno mamuli. En la isla estas telas se siguen haciendo para funerales y bodas, no solo para los visitantes: las piezas finas se entregan como contrapartida de la dote y envuelven a los difuntos.
Al comprar conviene preguntar si el tinte es natural o sintético; ambos son productos honrados si se etiquetan con honradez. En 2025-2026 las piezas pequeñas con tinte químico rondan las 250.000 rupias, y un hinggi grande, hilado a mano y con tintes naturales, va de alrededor de 1,5 millones a bastante más de 10 millones. Siempre que se pueda, es mejor comprar directamente a las tejedoras."""),
 id=("Tenun ikat adalah kain yang motifnya diikat dan dicelup pada benang sebelum ditenun; kata ikat berasal dari mengikat. Kain Sumba adalah ikat lungsin, yang secara tradisional diwarnai dengan nila untuk biru dan akar mengkudu untuk merah. Selembar kain besar berpewarna alam dapat memakan waktu sekitar empat bulan hingga setahun.",
 """Pekerjaannya dimulai jauh sebelum alat tenun dipasang. Berkas benang lungsin diikat rapat pada bagian yang tidak boleh terkena warna, lalu dicelup, dijemur, dibuka, dan diikat lagi untuk warna berikutnya. Baru setelah itu penenun, hampir selalu perempuan dengan alat tenun gedogan, memasukkan benang pakan. Nila menghasilkan biru dan akar mengkudu menghasilkan merah; kuning didapat dari kayu kuning atau kunyit. KBBI mencatat tenun ikat sebagai salah satu teknik bertenun yang terdapat di Nusa Tenggara.
Sumba Timur, di sekitar Waingapu, Kambera, Melolo, Rende, dan Kaliuda, adalah asal kain besar bermotif figuratif yang dimaksud para kolektor ketika menyebut ikat Sumba. Motifnya antara lain kuda, rusa, buaya, pohon tengkorak, dan perhiasan mamuli. Di pulau ini kain masih dibuat untuk pemakaman dan perkawinan, bukan hanya untuk pengunjung: kain halus menjadi balasan belis dan membungkus jenazah.
Saat membeli, tanyakan apakah pewarnanya alam atau sintetis; keduanya produk yang jujur asalkan dijelaskan apa adanya. Pada 2025-2026 kain kecil berpewarna kimia berharga sekitar Rp 250.000, sedangkan hinggi besar dari benang pintal tangan dan pewarna alam berkisar dari sekitar Rp 1,5 juta hingga jauh di atas Rp 10 juta. Sebisa mungkin belilah langsung dari penenunnya."""))

term("hinggi", "Hinggi", r"\bhinggi\b", ["sumba-ikat-weaving-where-to-buy", "kaliuda-village", "prailiu-village"], ["textiles"], aka=["inggi"],
 en=("A hinggi is the large rectangular men's cloth of Sumba, decorated with warp ikat. It is traditionally made in pairs: one cloth is wrapped around the hips and the other thrown over the shoulder. Hinggi are worn at ceremonies, exchanged between families and used to wrap the dead.",
 """A hinggi is usually woven as two identical panels that are sewn together, and the design mirrors from end to end and side to side. Noble hinggi are larger and dyed in red and indigo; in the past only nobles could wear them, mainly at festivals. A large piece of around 3 m by 1.2 m in natural dyes typically takes four to eight months and sometimes a year or more, the work of several members of a family.
East Sumba is where the famous figurative hinggi come from. On them you will see horses, a sign of wealth and prestige, along with deer, crocodiles, the skull tree and the mamuli ornament. In the Mangili area of the south-east, around Kaliuda, the cloth is called inggi and is always made in pairs, in morinda red and indigo.
These cloths are far more than clothing. They mark status, they are given as counter-gifts for the horses, buffalo and gold of the bridewealth, and at funerals a man's body is wrapped in hinggi. A large hand-spun, natural-dye hinggi cost from about Rp 1.5 million to over Rp 10 million in 2025-2026, and prices vary widely. If a host offers you a woven cloth to wear at a ceremony, accept it."""),
 es=("El hinggi es la gran tela rectangular masculina de Sumba, decorada con ikat de urdimbre. Tradicionalmente se hace por parejas: una se enrolla en las caderas y la otra se echa sobre el hombro. Se lleva en las ceremonias, se intercambia entre familias y sirve para envolver a los difuntos.",
 """Un hinggi suele tejerse en dos paños idénticos que luego se cosen, y el dibujo se refleja de un extremo a otro y de un lado a otro. Los hinggi nobles son más grandes y van teñidos de rojo e índigo; antiguamente solo podían llevarlos los nobles, sobre todo en las fiestas. Una pieza grande, de unos 3 metros por 1,2, con tintes naturales lleva normalmente entre cuatro y ocho meses, a veces un año o más, y es obra de varios miembros de una familia.
De Sumba Oriental salen los célebres hinggi figurativos. En ellos aparecen caballos, signo de riqueza y prestigio, junto a ciervos, cocodrilos, el árbol de los cráneos y el adorno mamuli. En la zona de Mangili, en el sureste, alrededor de Kaliuda, la tela se llama inggi y se hace siempre por parejas, en rojo de morinda e índigo.
Estas telas son mucho más que ropa. Señalan el rango, se entregan como contrapartida de los caballos, búfalos y oro de la dote, y en los funerales el cuerpo de un hombre se envuelve en hinggi. En 2025-2026 un hinggi grande, hilado a mano y con tintes naturales, costaba de alrededor de 1,5 millones de rupias a más de 10 millones, con grandes diferencias de precio. Si un anfitrión ofrece una tela tejida para llevarla en una ceremonia, lo correcto es aceptarla."""),
 id=("Hinggi adalah kain besar persegi panjang untuk laki-laki di Sumba, dihias dengan teknik ikat lungsin. Secara tradisi hinggi dibuat sepasang: satu dililitkan di pinggang, satu lagi disampirkan di bahu. Kain ini dipakai dalam upacara, dipertukarkan antarkeluarga, dan digunakan untuk membungkus jenazah.",
 """Hinggi biasanya ditenun dalam dua lembar kembar yang kemudian dijahit menjadi satu, dan motifnya berulang seperti cermin dari ujung ke ujung dan dari sisi ke sisi. Hinggi bangsawan lebih besar dan diwarnai merah serta nila; dahulu hanya bangsawan yang boleh memakainya, terutama pada pesta adat. Selembar hinggi besar berukuran sekitar 3 m x 1,2 m dengan pewarna alam umumnya dikerjakan empat sampai delapan bulan, kadang setahun atau lebih, oleh beberapa anggota keluarga.
Sumba Timur adalah asal hinggi bermotif figuratif yang terkenal. Di sana tampak kuda, lambang kekayaan dan gengsi, juga rusa, buaya, pohon tengkorak, dan perhiasan mamuli. Di wilayah Mangili di tenggara, sekitar Kaliuda, kain ini disebut inggi dan selalu dibuat sepasang, berwarna merah mengkudu dan nila.
Kain ini jauh lebih dari sekadar pakaian. Hinggi menandai kedudukan, menjadi balasan atas kuda, kerbau, dan emas dalam belis, dan pada pemakaman jenazah laki-laki dibungkus hinggi. Pada 2025-2026 hinggi besar dari benang pintal tangan dan pewarna alam berharga dari sekitar Rp 1,5 juta hingga lebih dari Rp 10 juta, dengan rentang yang lebar. Jika tuan rumah menawarkan kain tenun untuk dikenakan dalam upacara, terimalah."""))

term("lau", "Lau", r"\blau\b", ["sumba-ikat-weaving-where-to-buy", "pau-village", "sumba-weddings-funerals-ceremonies"], ["textiles"], aka=["lawu"],
 en=("A lau is the tubular skirt worn by Sumbanese women. Many lau are not ikat at all but plain weave decorated with supplementary warp, embroidery, beads or shells. Like the men's hinggi, they are worn at ceremonies, given at weddings and used to wrap the dead.",
 """Two words will get you through most conversations about Sumba textiles: hinggi for the men's cloth and lau for the women's skirt. The lau is sewn into a tube and worn wrapped around the body.
What sets many lau apart is the decoration. A lau pahudu is worked with supplementary warp, a technique called pahikung that produces raised patterns and is a separate skill from ikat. A lau hada is decorated with beads and shells; Wikipedia's article on the textiles of Sumba notes that such skirts are also called pakiri mbola, a name that refers to the bottom of the basket in which they are carried as part of marriage gifts. Occasionally a lau carries ikat as well.
The village of Pau, in the old Umalulu domain of East Sumba, is especially known for pahikung woven on backstrap looms, and in Prailiu, beside Waingapu, women weave both hinggi and lau with motifs of horses, crocodiles and prawns.
Lau move between families with the same weight as other cloths: they are part of the counter-gifts that answer the bridewealth, and at an important funeral a woman's body is wrapped in a lau. If you buy one, ask the weaver which technique was used and how long it took."""),
 es=("El lau es la falda tubular que visten las mujeres de Sumba. Muchos lau no son ikat, sino un tejido liso decorado con urdimbre suplementaria, bordados, cuentas o conchas. Como el hinggi masculino, se lleva en las ceremonias, se regala en las bodas y sirve para envolver a las difuntas.",
 """Con dos palabras se sale adelante en casi cualquier conversación sobre tejidos de Sumba: hinggi para la tela de los hombres y lau para la falda de las mujeres. El lau se cose en forma de tubo y se lleva ceñido al cuerpo.
Lo que distingue a muchos lau es la decoración. El lau pahudu se trabaja con urdimbre suplementaria, una técnica llamada pahikung que crea dibujos en relieve y que es un oficio distinto del ikat. El lau hada va adornado con cuentas y conchas; el artículo de Wikipedia sobre los tejidos de Sumba señala que estas faldas se llaman también pakiri mbola, un nombre que alude al fondo de la cesta en la que se llevan como parte de los regalos de boda. De vez en cuando un lau lleva también ikat.
El pueblo de Pau, en el antiguo dominio de Umalulu, en Sumba Oriental, es conocido sobre todo por el pahikung tejido en telares de cintura, y en Prailiu, junto a Waingapu, las mujeres tejen hinggi y lau con motivos de caballos, cocodrilos y gambas.
Los lau circulan entre familias con el mismo peso que las demás telas: forman parte de los regalos con que se responde a la dote, y en un funeral importante el cuerpo de una mujer se envuelve en un lau. Quien compre uno hará bien en preguntar a la tejedora qué técnica ha usado y cuánto tiempo le ha llevado."""),
 id=("Lau adalah sarung berbentuk tabung yang dikenakan perempuan Sumba. Banyak lau sama sekali bukan ikat, melainkan tenun polos yang dihias dengan lungsin tambahan, sulaman, manik-manik, atau kerang. Seperti hinggi untuk laki-laki, lau dipakai dalam upacara, diberikan pada perkawinan, dan digunakan untuk membungkus jenazah.",
 """Dua kata sudah cukup untuk hampir semua obrolan tentang kain Sumba: hinggi untuk kain laki-laki dan lau untuk sarung perempuan. Lau dijahit menjadi tabung dan dikenakan dengan dililitkan di badan.
Yang membedakan banyak lau adalah hiasannya. Lau pahudu dikerjakan dengan lungsin tambahan, teknik bernama pahikung yang menghasilkan motif timbul dan merupakan keterampilan tersendiri, berbeda dari ikat. Lau hada dihias manik-manik dan kerang; artikel Wikipedia tentang tekstil Sumba mencatat bahwa sarung semacam ini juga disebut pakiri mbola, nama yang merujuk pada dasar keranjang tempat kain itu dibawa sebagai bagian dari pemberian perkawinan. Sesekali lau juga memuat ikat.
Kampung Pau, di bekas wilayah kerajaan Umalulu di Sumba Timur, terutama dikenal karena pahikung yang ditenun dengan alat tenun gedogan. Di Prailiu, di sebelah Waingapu, para perempuan menenun hinggi dan lau bermotif kuda, buaya, dan udang.
Lau berpindah antarkeluarga dengan bobot yang sama seperti kain lain: lau termasuk pemberian balasan atas belis, dan pada pemakaman penting jenazah perempuan dibungkus lau. Jika membeli, tanyakan kepada penenunnya teknik apa yang dipakai dan berapa lama pengerjaannya."""))

term("mamuli", "Mamuli", r"mamuli", ["sumba-ikat-weaving-where-to-buy", "sumba-weddings-funerals-ceremonies"], ["mamuli"],
 en=("A mamuli is a precious-metal ornament of Sumba, usually gold or silver, given as part of the bridewealth and kept as a family heirloom. Its shape represents the female body and stands for woman as the giver of life. It is worn as an ear ornament or pendant and appears as a motif on ikat cloth, a symbol of fertility and rank.",
 """Mamuli are among the most important valuables in Sumbanese exchange. When two clans are joined by marriage, the groom's side gives horses and buffalo, often with a gold ear pendant, and the bride's side answers with pigs and woven cloth. The Wikipedia article on mamuli describes the same movement in anthropological terms: the wife-taking group gives mamuli to the wife-givers, and the ornaments then pass from family to family and from one generation to the next.
The same article distinguishes two forms. The plain type is diamond-shaped with a hollow centre and a slit, and is regarded as female. The decorated type has extra finials at the base, sometimes with small figures such as roosters, horsemen or buffalo, and is regarded as male. They were worn on the ear lobes, and very large pieces as neck pendants.
Old mamuli are not everyday jewellery. They are kept in the treasuries of clan leaders with other heirlooms and are treated as objects that link the living to the ancestors, which is why they are rarely brought out.
Travellers are most likely to see the shape woven into cloth. On East Sumba hinggi the mamuli sits among horses, deer and skull trees. If a family shows you an heirloom, look, do not touch, and ask before photographing."""),
 es=("El mamuli es un adorno de metal precioso de Sumba, por lo general de oro o plata, que se entrega como parte de la dote y se guarda como reliquia familiar. Su forma representa el cuerpo femenino y alude a la mujer como dadora de vida. Se lleva como pendiente o colgante y aparece como motivo en las telas ikat, símbolo de fertilidad y de rango.",
 """Los mamuli están entre los bienes más valiosos de los intercambios sumbaneses. Cuando un matrimonio une a dos clanes, la familia del novio entrega caballos y búfalos, a menudo con un pendiente de oro, y la de la novia responde con cerdos y telas tejidas. El artículo de Wikipedia sobre el mamuli describe el mismo movimiento en términos antropológicos: el grupo que recibe a la esposa entrega mamuli al que la da, y después los adornos pasan de familia en familia y de una generación a otra.
El mismo artículo distingue dos formas. La lisa tiene forma de rombo, con el centro hueco y una hendidura, y se considera femenina. La decorada añade remates en la base, a veces con figurillas de gallos, jinetes o búfalos, y se considera masculina. Se llevaban en los lóbulos de las orejas, y las piezas muy grandes, como colgantes.
Los mamuli antiguos no son joyas de diario. Se guardan en los tesoros de los jefes de clan junto con otras reliquias y se tratan como objetos que unen a los vivos con los antepasados, por lo que rara vez se sacan.
Lo más probable es que el viajero vea la forma tejida en una tela. En los hinggi de Sumba Oriental el mamuli aparece entre caballos, ciervos y árboles de cráneos. Si una familia enseña una reliquia, se mira, no se toca, y se pide permiso antes de fotografiarla."""),
 id=("Mamuli adalah perhiasan logam mulia dari Sumba, biasanya emas atau perak, yang diberikan sebagai bagian dari belis dan disimpan sebagai pusaka keluarga. Bentuknya melambangkan tubuh perempuan sebagai pemberi kehidupan. Mamuli dipakai sebagai anting atau liontin dan muncul sebagai motif pada kain ikat, lambang kesuburan dan kedudukan.",
 """Mamuli termasuk benda paling berharga dalam pertukaran adat Sumba. Ketika perkawinan menyatukan dua kabihu, pihak laki-laki memberikan kuda dan kerbau, sering kali disertai anting emas, dan pihak perempuan membalas dengan babi serta kain tenun. Artikel Wikipedia tentang mamuli menguraikan arus yang sama dalam istilah antropologi: kelompok penerima istri menyerahkan mamuli kepada kelompok pemberi istri, lalu perhiasan itu berpindah dari keluarga ke keluarga dan dari generasi ke generasi.
Artikel yang sama membedakan dua bentuk. Yang polos berbentuk belah ketupat dengan bagian tengah cekung dan bercelah, dan dianggap feminin. Yang berhias memiliki tambahan di bagian bawah, kadang dengan figur kecil seperti ayam jantan, penunggang kuda, atau kerbau, dan dianggap maskulin. Mamuli dikenakan di cuping telinga, sedangkan yang sangat besar dipakai sebagai liontin.
Mamuli tua bukan perhiasan sehari-hari. Benda ini disimpan dalam perbendaharaan pemimpin kabihu bersama pusaka lain dan diperlakukan sebagai penghubung antara orang hidup dan leluhur, sehingga jarang dikeluarkan.
Pelancong paling mungkin melihat bentuknya pada kain. Pada hinggi Sumba Timur, mamuli tampil di antara kuda, rusa, dan pohon tengkorak. Jika sebuah keluarga memperlihatkan pusakanya, cukup lihat, jangan disentuh, dan mintalah izin sebelum memotret."""))

term("belis", "Belis", r"\bbelis\b", ["sumba-weddings-funerals-ceremonies", "sumba-horses-sandalwood-pony"], ["textiles"],
 en=("Belis is the bridewealth exchanged at a Sumbanese marriage. The groom's family gives horses and buffalo, often with gold ornaments, and the bride's family answers with pigs and woven cloth. It is not a simple payment: it seals an alliance between two clans.",
 """A Sumbanese marriage joins two clans, and the belis is at its heart. The exact amount depends on the family, the clan and the status of the bride, and the negotiations can take a long time. Anthropologists working in Kodi and East Sumba recorded minimum bridewealths of around ten animals, with larger amounts depending on the bride's family.
Horses are a central part of it. A family's standing in the community has long been tied to how many good horses it owns, and horses were also given in the past to make peace between clans. Gold comes in the form of ornaments such as the mamuli. In return, the bride's side gives pigs and textiles; fine cloths are the recognised counter-payment for the animals and gold.
Part of the bridewealth is often deferred. That is deliberate: an unfinished exchange keeps the relationship between the two families alive for years.
If you are invited to a wedding you will see speeches, negotiations, gongs, dancing and a big shared meal. You are not part of the exchange, and nobody will expect you to bring a horse. Go with your host, ask them what gift suits an outsider and accept the betel nut or coffee you are offered."""),
 es=("El belis es la dote que se intercambia en un matrimonio sumbanés. La familia del novio entrega caballos y búfalos, a menudo con adornos de oro, y la de la novia responde con cerdos y telas tejidas. No es un simple pago: sella una alianza entre dos clanes.",
 """Un matrimonio sumbanés une a dos clanes, y el belis está en el centro. La cantidad exacta depende de la familia, del clan y del rango de la novia, y las negociaciones pueden alargarse mucho. Los antropólogos que trabajaron en Kodi y en Sumba Oriental registraron dotes mínimas de unos diez animales, con cifras mayores según la familia de la novia.
Los caballos son una parte esencial. El prestigio de una familia ha estado ligado durante mucho tiempo al número de buenos caballos que posee, y antiguamente también se regalaban caballos para sellar la paz entre clanes. El oro llega en forma de adornos como el mamuli. A cambio, la parte de la novia entrega cerdos y tejidos: las telas finas son la contrapartida reconocida de los animales y el oro.
Con frecuencia una parte de la dote se aplaza. Es deliberado: un intercambio sin cerrar mantiene viva durante años la relación entre las dos familias.
Quien esté invitado a una boda verá discursos, negociaciones, gongs, danzas y una gran comida compartida. El invitado no forma parte del intercambio y nadie espera que traiga un caballo. Lo correcto es ir con el anfitrión, preguntarle qué regalo conviene a un forastero y aceptar la nuez de betel o el café que se ofrezcan."""),
 id=("Belis adalah mas kawin adat yang dipertukarkan dalam perkawinan orang Sumba. Keluarga laki-laki memberikan kuda dan kerbau, sering kali disertai perhiasan emas, dan keluarga perempuan membalas dengan babi serta kain tenun. Belis bukan sekadar pembayaran: belis mengikat persekutuan dua kabihu.",
 """Perkawinan di Sumba menyatukan dua kabihu, dan belis menjadi intinya. Jumlah pastinya bergantung pada keluarga, kabihu, dan kedudukan mempelai perempuan, dan perundingannya bisa berlangsung lama. Para antropolog yang meneliti di Kodi dan Sumba Timur mencatat belis minimal sekitar sepuluh ekor hewan, dengan jumlah lebih besar bergantung pada keluarga mempelai perempuan.
Kuda adalah bagian utamanya. Kedudukan sebuah keluarga sejak lama dikaitkan dengan banyaknya kuda bagus yang dimiliki, dan dahulu kuda juga diberikan untuk mendamaikan kabihu yang berselisih. Emas hadir dalam bentuk perhiasan seperti mamuli. Sebagai balasan, pihak perempuan memberikan babi dan kain; kain halus adalah imbalan yang diakui atas hewan dan emas.
Sebagian belis kerap ditunda pembayarannya. Itu disengaja: pertukaran yang belum tuntas menjaga hubungan kedua keluarga tetap hidup selama bertahun-tahun.
Jika diundang ke pesta perkawinan, Anda akan menyaksikan pidato adat, perundingan, bunyi gong, tarian, dan makan bersama. Anda bukan bagian dari pertukaran itu, dan tidak ada yang berharap Anda membawa kuda. Datanglah bersama tuan rumah, tanyakan hadiah apa yang pantas bagi orang luar, dan terimalah sirih pinang atau kopi yang disuguhkan."""))

term("uma-mbatangu", {"en": "Uma mbatangu (peaked house)", "es": "Uma mbatangu (casa de tejado alto)", "id": "Uma mbatangu (rumah menara)"}, r"uma mbatangu|uma hori|uma kalada", ["marapu-ikat-traditional-villages", "prailiu-village", "ratenggaro-village", "wainyapu-village"], ["arch"], aka=["uma hori", "uma kalada"],
 en=("Uma mbatangu, the peaked house, is the traditional Sumbanese clan house with a tall tower roof of thatch. It has three levels: animals below, the family in the middle and, under the roof peak, the space of the ancestors and the sacred heirlooms. Villages of these houses stand around stone tombs.",
 """The high roof is what you notice first on any road in western Sumba, and it is not decoration. In Sumbanese belief the house mirrors the order of the world: one level for the dead or the animals below, one for the living, and the roof for the ancestors and spirits. The architecture site ArchEyes describes the upper space as the place where sacred heirlooms are stored and offerings to the ancestors are made, entered only rarely and only by older men.
The same source describes four central posts around a hearth, each with its own role in the life of the household, and a roof of dense alang-alang grass tied to battens. A house without the central peak, called uma kamadungu, serves less ceremonial purposes. Rows of houses face a central plaza that holds the megalithic tombs, so houses and graves stand together.
Names vary across the island. In Prailiu, beside Waingapu, the houses are called uma mbatangu or uma hori; in Wainyapu, in Kodi, an Indonesian report counts around 60 uma kalada. Ratenggaro, also in Kodi, is known for some of the tallest roofs in Sumba.
Thatch burns. In October 2017 a fire swept through Tarung, in Waikabubak, and burned all 30 houses; most have since been rebuilt in the original style. These are homes: ask before entering."""),
 es=("La uma mbatangu, la casa de tejado alto, es la vivienda tradicional de los clanes de Sumba, rematada por una alta torre de paja. Tiene tres niveles: los animales abajo, la familia en medio y, bajo la cumbre, el espacio de los antepasados y de las reliquias sagradas. Los pueblos formados por estas casas se levantan alrededor de tumbas de piedra.",
 """El tejado alto es lo primero que se ve en cualquier carretera del oeste de Sumba, y no es un adorno. En la creencia sumbanesa la casa refleja el orden del mundo: un nivel para los muertos o los animales, abajo; otro para los vivos, y el tejado para los antepasados y los espíritus. El sitio de arquitectura ArchEyes describe el espacio superior como el lugar donde se guardan las reliquias sagradas y se hacen las ofrendas a los antepasados, al que solo entran, y rara vez, los hombres de más edad.
La misma fuente describe cuatro postes centrales en torno a un hogar, cada uno con su función en la vida de la casa, y una cubierta de densa hierba alang-alang atada a listones. La casa sin torre central, llamada uma kamadungu, tiene usos menos ceremoniales. Las hileras de casas dan a una plaza central donde están las tumbas megalíticas, de modo que casas y sepulturas conviven.
Los nombres cambian de una zona a otra. En Prailiu, junto a Waingapu, las casas se llaman uma mbatangu o uma hori; en Wainyapu, en Kodi, un reportaje indonesio cuenta unas 60 uma kalada. Ratenggaro, también en Kodi, es conocido por algunos de los tejados más altos de la isla.
La paja arde. En octubre de 2017 un incendio arrasó Tarung, en Waikabubak, y quemó sus 30 casas; la mayoría se han reconstruido con el estilo original. Son hogares: hay que pedir permiso antes de entrar."""),
 id=("Uma mbatangu, rumah menara, adalah rumah adat kabihu di Sumba dengan atap ilalang yang menjulang tinggi. Rumah ini bertingkat tiga: ternak di kolong, keluarga di tengah, dan di bawah puncak atap ruang bagi leluhur serta benda pusaka. Kampung yang tersusun dari rumah-rumah ini berdiri mengelilingi kubur batu.",
 """Atap yang menjulang adalah hal pertama yang terlihat di jalan mana pun di Sumba bagian barat, dan itu bukan hiasan. Dalam kepercayaan orang Sumba, rumah mencerminkan tatanan dunia: satu tingkat untuk orang mati atau ternak di bawah, satu untuk orang hidup, dan atap untuk leluhur serta roh. Situs arsitektur ArchEyes menggambarkan ruang atas sebagai tempat menyimpan benda pusaka dan meletakkan persembahan bagi leluhur, yang hanya sesekali dimasuki oleh laki-laki yang dituakan.
Sumber yang sama menyebut empat tiang utama di sekeliling tungku, masing-masing dengan peran sendiri dalam kehidupan rumah, serta atap ilalang tebal yang diikat pada reng. Rumah tanpa menara, disebut uma kamadungu, dipakai untuk keperluan yang kurang bersifat upacara. Deretan rumah menghadap pelataran tengah tempat kubur batu megalitik berada, sehingga rumah dan kubur berdampingan.
Namanya berbeda dari satu wilayah ke wilayah lain. Di Prailiu, di sebelah Waingapu, rumah ini disebut uma mbatangu atau uma hori; di Wainyapu, Kodi, sebuah laporan mencatat sekitar 60 uma kalada. Ratenggaro, juga di Kodi, dikenal dengan atap yang termasuk paling tinggi di Sumba.
Ilalang mudah terbakar. Pada Oktober 2017 kebakaran melanda Tarung di Waikabubak dan menghanguskan 30 rumahnya; sebagian besar telah dibangun kembali dengan gaya asli. Ini rumah tinggal: mintalah izin sebelum masuk."""))

term("kampung-adat", {"en": "Kampung adat (traditional village)", "es": "Kampung adat (pueblo tradicional)", "id": "Kampung adat"}, {"en": r"kampung adat|traditional villages?", "es": r"kampung adat|pueblos? tradicional(?:es)?", "id": r"kampung adat"}, ["marapu-ikat-traditional-villages", "praijing-village", "ratenggaro-village", "tarung-village"], ["arch"], pron="KAHM-poong AH-daht",
 en=("A kampung adat is a customary village: a settlement where clans keep their ancestral houses and many families still follow Marapu, the ancestral belief of Sumba. Tall-roofed houses stand around megalithic tombs. These villages are homes, not museums, and visitors are guests.",
 """The Indonesian words are simple: kampung means village and adat means custom or customary law. On road signs and maps in Sumba you will see names such as Kampung Adat Ratenggaro or Kampung Adat Wainyapu. Rows of houses face a central space that holds the stone tombs and other sacred objects, and some houses have particular ritual duties, such as keeping heirlooms or deciding when a sacred month begins.
The best-known villages are in the west and south-west: Praijing and Tarung at Waikabubak, Ratenggaro and Wainyapu in Kodi. In the east, Prailiu beside Waingapu, Pau and Rende are also weaving villages.
A visit follows the same pattern almost everywhere. There is usually no ticket office: you sign a guest book and leave a donation, and around IDR 10,000 to 40,000 per person is common. A small bag of sirih pinang, betel and areca nut bought at a market, is the traditional gift. Dress modestly, ask before entering a house and before photographing anyone, and never climb or sit on the tombs or touch ritual objects.
During ritual periods, such as Wulla Poddu around Waikabubak in roughly October and November or the days around the Pasola, some areas are closed to outsiders. Go with a local guide and ask first."""),
 es=("Un kampung adat es un pueblo de la costumbre: un asentamiento donde los clanes conservan sus casas ancestrales y muchas familias siguen el marapu, la creencia ancestral de Sumba. Las casas de tejado alto rodean las tumbas megalíticas. Son hogares, no museos, y quien los visita es un invitado.",
 """Las palabras indonesias son sencillas: kampung significa pueblo y adat, costumbre o derecho consuetudinario. En las señales y los mapas de Sumba aparecen nombres como Kampung Adat Ratenggaro o Kampung Adat Wainyapu. Las hileras de casas dan a un espacio central donde están las tumbas de piedra y otros objetos sagrados, y algunas casas tienen deberes rituales concretos, como custodiar reliquias o decidir cuándo empieza un mes sagrado.
Los pueblos más conocidos están en el oeste y el suroeste: Praijing y Tarung en Waikabubak, Ratenggaro y Wainyapu en Kodi. En el este, Prailiu, junto a Waingapu, Pau y Rende son además pueblos de tejedoras.
La visita sigue casi siempre el mismo patrón. No suele haber taquilla: se firma un libro de visitas y se deja un donativo, normalmente de unas 10.000 a 40.000 rupias por persona. Una bolsita de sirih pinang, betel y nuez de areca comprada en un mercado, es el regalo tradicional. Hay que vestir con discreción, pedir permiso antes de entrar en una casa y de fotografiar a alguien, y no subirse ni sentarse nunca en las tumbas ni tocar los objetos rituales.
Durante los periodos rituales, como el Wulla Poddu en torno a Waikabubak hacia octubre y noviembre o los días de la Pasola, algunas zonas se cierran a los forasteros. Conviene ir con un guía local y preguntar antes."""),
 id=("Kampung adat adalah permukiman tempat kabihu-kabihu mempertahankan rumah leluhurnya dan banyak keluarga masih menganut Marapu, kepercayaan leluhur orang Sumba. Rumah-rumah beratap tinggi berdiri mengelilingi kubur batu megalitik. Kampung ini rumah tinggal, bukan museum, dan pengunjung adalah tamu.",
 """Di papan penunjuk jalan dan peta Sumba, Anda akan menemukan nama seperti Kampung Adat Ratenggaro atau Kampung Adat Wainyapu. Deretan rumah menghadap pelataran tengah tempat kubur batu dan benda keramat lain berada, dan beberapa rumah memegang tugas ritual tertentu, misalnya menyimpan pusaka atau memutuskan kapan bulan suci dimulai.
Kampung yang paling dikenal berada di barat dan barat daya: Praijing dan Tarung di Waikabubak, Ratenggaro dan Wainyapu di Kodi. Di timur, Prailiu di sebelah Waingapu, Pau, dan Rende juga merupakan kampung penenun.
Tata cara berkunjung hampir sama di mana-mana. Biasanya tidak ada loket: pengunjung mengisi buku tamu dan memberi donasi, umumnya sekitar Rp 10.000 sampai Rp 40.000 per orang. Sebungkus kecil sirih pinang yang dibeli di pasar adalah buah tangan tradisional. Berpakaianlah sopan, mintalah izin sebelum masuk rumah dan sebelum memotret siapa pun, dan jangan pernah menaiki atau menduduki kubur batu ataupun menyentuh benda ritual.
Selama masa ritual, seperti Wulla Poddu di sekitar Waikabubak kira-kira pada Oktober dan November atau hari-hari di sekitar Pasola, sebagian area tertutup bagi orang luar. Datanglah bersama pemandu setempat dan bertanyalah lebih dulu."""), nolink=())

term("kubur-batu", {"en": "Megalithic tomb (kubur batu)", "es": "Tumba megalítica (kubur batu)", "id": "Kubur batu"}, {"en": r"megalithic tombs?|kubur batu|stone tombs?", "es": r"tumbas? megalíticas?|kubur batu|tumbas? de piedra", "id": r"kubur batu"}, ["gallubakul-village", "pasunga-village", "sumba-weddings-funerals-ceremonies", "marapu-ikat-traditional-villages"], ["stone", "arch"], pron="KOO-boor BAH-too",
 en=("A megalithic tomb, kubur batu in Indonesian, is the great stone grave that stands in front of the houses in Sumba's traditional villages. In Sumbanese tradition, linked to the Marapu belief in the ancestors, the tomb is the house of the dead. Such tombs are still being made, and dragging and raising the stone is one of the biggest events in the life of a clan.",
 """Sumba is one of the few places where megaliths are not archaeology but current practice. Nobles are buried in stone tombs, the carvings show the rank of the dead, and building one takes time and the collective effort of a community: moving a great stone can involve hundreds or even thousands of people. A 2004 report carried by Stone Pages described about 300 men hauling a limestone slab on a wooden sled for nearly 2 km in western Sumba, and noted that trucks and cheaper cement graves were beginning to replace hand-hauling.
The largest tombs are in Anakalang, Central Sumba. At Gallubakul the tomb of Umbu Sawola, cut from a single stone of about 70 tonnes, was long described as the heaviest on the island; in 2022 the tomb of Umbu Jadar, at 79 tonnes, surpassed it. Nearby Pasunga has one of the most richly carved. In the east, the tomb of the last king of Prailiu is reported to weigh around 40 tons, and Rende is known for tombs topped with carved animal figures. In Kodi, Wainyapu and Ratenggaro count hundreds.
Etiquette is strict and simple: these are graves. Never climb or sit on a tomb, do not touch it, and ask before photographing. Sign the guest book and leave a donation."""),
 es=("La tumba megalítica, kubur batu en indonesio, es la gran sepultura de piedra que se alza delante de las casas en los pueblos tradicionales de Sumba. En la tradición sumbanesa, ligada a la creencia marapu en los antepasados, la tumba es la casa de los muertos. Todavía se construyen, y arrastrar y levantar la piedra es uno de los grandes acontecimientos en la vida de un clan.",
 """Sumba es uno de los pocos lugares donde los megalitos no son arqueología, sino una práctica viva. Los nobles se entierran en tumbas de piedra, las tallas indican el rango del difunto y levantar una exige tiempo y el esfuerzo de toda una comunidad: mover una gran piedra puede reunir a cientos o incluso miles de personas. Una crónica de 2004 recogida por Stone Pages describía a unos 300 hombres arrastrando una losa de caliza sobre un trineo de madera durante casi 2 kilómetros en el oeste de la isla, y señalaba que los camiones y las tumbas de cemento, más baratas, empezaban a sustituir al arrastre a mano.
Las mayores están en Anakalang, en Sumba Central. En Gallubakul, la tumba de Umbu Sawola, tallada en una sola piedra de unas 70 toneladas, se describió durante mucho tiempo como la más pesada de la isla; en 2022 la superó la de Umbu Jadar, de 79 toneladas. La cercana Pasunga tiene una de las más ricamente talladas. En el este, la tumba del último rey de Prailiu pesa, según se dice, unas 40 toneladas, y Rende es conocido por sus tumbas coronadas con figuras de animales. En Kodi, Wainyapu y Ratenggaro las cuentan por centenares.
La norma es estricta y sencilla: son sepulturas. No hay que subirse ni sentarse nunca en una tumba ni tocarla, y hay que pedir permiso antes de fotografiar. Se firma el libro de visitas y se deja un donativo."""),
 id=("Kubur batu adalah makam batu besar yang berdiri di depan rumah-rumah di kampung adat Sumba. Dalam tradisi orang Sumba, yang berkaitan dengan kepercayaan Marapu kepada leluhur, kubur adalah rumah bagi orang mati. Kubur batu masih dibuat sampai sekarang, dan menarik serta menegakkan batunya termasuk peristiwa terbesar dalam kehidupan sebuah kabihu.",
 """Sumba adalah satu dari sedikit tempat di mana megalit bukan arkeologi, melainkan tradisi yang masih berjalan. Bangsawan dimakamkan dalam kubur batu, ukirannya menunjukkan kedudukan mendiang, dan pembuatannya memerlukan waktu serta gotong royong seluruh komunitas: memindahkan batu besar bisa melibatkan ratusan bahkan ribuan orang. Laporan tahun 2004 yang dimuat Stone Pages menggambarkan sekitar 300 laki-laki menarik lempeng batu kapur di atas kereta kayu sejauh hampir 2 km di Sumba bagian barat, dan mencatat bahwa truk serta kubur semen yang lebih murah mulai menggantikan tarik batu dengan tangan.
Kubur terbesar berada di Anakalang, Sumba Tengah. Di Gallubakul, kubur Umbu Sawola dari sebongkah batu seberat sekitar 70 ton lama disebut sebagai yang terberat di pulau ini; pada 2022 kubur Umbu Jadar seberat 79 ton melampauinya. Pasunga di dekatnya memiliki salah satu kubur dengan ukiran paling kaya. Di timur, kubur raja terakhir Prailiu dilaporkan berbobot sekitar 40 ton, dan Rende dikenal dengan kubur bermahkota patung hewan. Di Kodi, Wainyapu dan Ratenggaro memiliki ratusan kubur batu.
Tata kramanya tegas dan sederhana: ini makam. Jangan pernah menaiki, menduduki, atau menyentuh kubur, dan mintalah izin sebelum memotret. Isilah buku tamu dan tinggalkan donasi."""))

term("nyale", "Nyale", r"nyale", ["pasola-2027-dates", "pasola-explained", "marosi-beach"], ["palola", "detik"],
 en=("Nyale are sea worms that appear on Sumba's shores around the full moon in February and March. Their arrival is the sign the Rato elders wait for: the Pasola can only take place once the worms have been gathered. Plump, healthy worms are read as the promise of a good harvest.",
 """The nyale ceremony opens the Pasola. The worms are gathered at dawn, the elders examine them, and what they find is read as a forecast for the farming year. The month before is a sacred period, the month of nyale, with taboos for the local community such as not holding parties or building houses. Because everything depends on the worms and the moon, Pasola dates are confirmed only weeks ahead.
The name is used across Indonesia for the palolo worm. Wikipedia's article on the species Palola viridis lists nyale and wawo as its Indonesian names and describes a marine worm of tropical reefs whose tail segments break off and float to the surface in a mass spawning timed by the moon, for a few nights each year. On Lombok the same event is celebrated as the Bau Nyale festival between February and March. In several places the worms are gathered and eaten.
In Sumba the worms are said to appear along the Lamboya shore near Marosi beach, in the heart of Pasola country.
For visitors the nyale gathering is a ritual moment, not an excursion. A guide or driver from the area knows when and where it happens and whether outsiders are welcome. Keep your distance, keep lights and cameras down unless invited, and follow the elders' instructions."""),
 es=("Los nyale son gusanos marinos que aparecen en las costas de Sumba en torno a la luna llena de febrero y marzo. Su llegada es la señal que esperan los ancianos rato: la Pasola solo puede celebrarse cuando se han recogido. Si llegan gordos y sanos, se interpreta como promesa de buena cosecha.",
 """La ceremonia de los nyale abre la Pasola. Los gusanos se recogen al amanecer, los ancianos los examinan y lo que encuentran se lee como un pronóstico para el año agrícola. El mes anterior es un periodo sagrado, el mes de los nyale, con tabúes para la comunidad, como no celebrar fiestas ni construir casas. Como todo depende de los gusanos y de la luna, las fechas de la Pasola se confirman con pocas semanas de antelación.
El nombre se usa en toda Indonesia para el gusano palolo. El artículo de Wikipedia sobre la especie Palola viridis recoge nyale y wawo como sus nombres indonesios y describe un gusano marino de los arrecifes tropicales cuyos segmentos posteriores se desprenden y suben a la superficie en un desove masivo acompasado con la luna, durante unas pocas noches al año. En Lombok el mismo fenómeno se celebra entre febrero y marzo con la fiesta del Bau Nyale. En varios lugares los gusanos se recogen y se comen.
En Sumba se dice que aparecen en la costa de Lamboya, cerca de la playa de Marosi, en pleno territorio de la Pasola.
Para el visitante, la recogida de los nyale es un momento ritual, no una excursión. Un guía o conductor de la zona sabe cuándo y dónde ocurre y si los forasteros son bienvenidos. Hay que guardar las distancias, no usar luces ni cámaras salvo invitación y seguir las indicaciones de los ancianos."""),
 id=("Nyale adalah cacing laut yang muncul di pantai-pantai Sumba sekitar bulan purnama pada Februari dan Maret. Kemunculannya adalah tanda yang ditunggu para Rato: Pasola baru bisa digelar setelah nyale didapat. Nyale yang gemuk dan sehat dibaca sebagai pertanda panen yang baik.",
 """Upacara nyale membuka Pasola. Cacing dikumpulkan saat fajar, para tetua memeriksanya, dan hasilnya dibaca sebagai ramalan untuk tahun pertanian. Sebulan sebelumnya adalah masa keramat, bulan nyale, dengan pantangan bagi warga seperti tidak mengadakan pesta atau membangun rumah. Karena semuanya bergantung pada nyale dan bulan, tanggal Pasola baru dipastikan beberapa minggu sebelumnya.
Nama ini dipakai di berbagai daerah di Indonesia untuk cacing palolo. Artikel Wikipedia tentang spesies Palola viridis mencantumkan nyale dan wawo sebagai namanya di Indonesia dan menggambarkan cacing laut penghuni terumbu tropis yang ruas ekornya terlepas lalu naik ke permukaan dalam pemijahan massal mengikuti fase bulan, selama beberapa malam setiap tahun. Di Lombok peristiwa yang sama dirayakan sebagai festival Bau Nyale antara Februari dan Maret. Di sejumlah tempat cacing ini dikumpulkan dan dimakan.
Di Sumba, nyale disebut muncul di pesisir Lamboya di dekat Pantai Marosi, di jantung wilayah Pasola.
Bagi pengunjung, pengambilan nyale adalah momen ritual, bukan wisata. Pemandu atau sopir dari daerah itu tahu kapan dan di mana berlangsungnya serta apakah orang luar boleh hadir. Jagalah jarak, jangan menyalakan lampu atau kamera kecuali diundang, dan ikuti arahan para tetua."""))

term("wulla-poddu", "Wulla Poddu", r"wulla poddu", ["tarung-village", "waikabubak-town", "praijing-village"], ["gnfi"],
 en=("Wulla Poddu is the sacred month of the Marapu communities of West Sumba, observed in roughly October and November. The name means bitter month, because of the prohibitions kept during it. It is a period of austere rites that ends with offerings, song and dance.",
 """According to the West Sumba government, as quoted by Good News From Indonesia, wulla means month and poddu means bitter. During the month, everyday work in the fields, funeral ceremonies and other festivities are prohibited. The cycle opens with a meeting of two elders, the Rato Rumata, who set the starting date, and passes through a long series of rites: the ancestors are invited to witness, the rules are announced, the village is cleansed, and dances and songs are rehearsed. The peak ceremony runs from night until morning, and the month closes with a public announcement that Wulla Poddu is over.
The same source says nearly all of West Sumba takes part, with the largest rituals in the Loli area around Waikabubak, in the villages of Tambera, Tarung, Bondo Maroto and Gollu, and others in Lamboya, Wanokaka and Tana Righu. In Tarung, some houses keep sacred heirlooms and others are responsible for deciding when the month begins.
For visitors this is the most delicate time of year in the Waikabubak villages. There are strict ritual rules, and some ceremonies and areas are closed or restricted. If you visit Tarung or Praijing then, go only with a local guide, ask before entering and follow instructions. Dates change every year, so check locally."""),
 es=("El Wulla Poddu es el mes sagrado de las comunidades marapu de Sumba Occidental, que se guarda hacia octubre y noviembre. El nombre significa mes amargo, por las prohibiciones que se respetan mientras dura. Es un periodo de ritos austeros que termina con ofrendas, cantos y danzas.",
 """Según el gobierno de Sumba Occidental, citado por Good News From Indonesia, wulla significa mes y poddu, amargo. Durante ese mes quedan prohibidos el trabajo diario en el campo, las ceremonias fúnebres y otras celebraciones. El ciclo se abre con la reunión de dos ancianos, los Rato Rumata, que fijan la fecha de inicio, y recorre una larga serie de ritos: se invita a los antepasados a ser testigos, se anuncian las normas, se purifica el pueblo y se ensayan danzas y cantos. La ceremonia culminante dura de la noche a la mañana, y el mes se cierra con el anuncio público de que el Wulla Poddu ha terminado.
La misma fuente señala que participa casi toda Sumba Occidental, con los rituales más importantes en la zona de Loli, alrededor de Waikabubak, en los pueblos de Tambera, Tarung, Bondo Maroto y Gollu, y otros en Lamboya, Wanokaka y Tana Righu. En Tarung, unas casas custodian reliquias sagradas y otras tienen la responsabilidad de decidir cuándo empieza el mes.
Para el visitante es la época más delicada del año en los pueblos de Waikabubak. Rigen normas rituales estrictas, y algunas ceremonias y zonas quedan cerradas o restringidas. Quien visite entonces Tarung o Praijing debe ir solo con un guía local, pedir permiso antes de entrar y seguir sus indicaciones. Las fechas cambian cada año, así que conviene informarse sobre el terreno."""),
 id=("Wulla Poddu adalah bulan suci komunitas Marapu di Sumba Barat, yang dijalani kira-kira pada Oktober dan November. Namanya berarti bulan pahit, karena berbagai pantangan yang dipegang sepanjang bulan itu. Ini masa ritus yang penuh pengekangan diri dan ditutup dengan persembahan, nyanyian, serta tarian.",
 """Menurut Pemerintah Kabupaten Sumba Barat, seperti dikutip Good News From Indonesia, wulla berarti bulan dan poddu berarti pahit. Sepanjang bulan itu, pekerjaan sehari-hari di ladang, upacara kematian, dan pesta lain dilarang. Rangkaiannya dibuka dengan pertemuan dua tetua, Rato Rumata, untuk menetapkan tanggal awal, lalu melewati deretan ritus yang panjang: leluhur diundang menjadi saksi, aturan diumumkan, kampung dibersihkan, tarian dan nyanyian dilatih. Upacara puncak berlangsung dari malam hingga pagi, dan bulan itu ditutup dengan pengumuman kepada warga bahwa Wulla Poddu telah selesai.
Sumber yang sama menyebut hampir seluruh Sumba Barat ikut menjalaninya, dengan ritual terbesar di wilayah Loli di sekitar Waikabubak, yakni di Kampung Tambera, Tarung, Bondo Maroto, dan Gollu, serta ritual lain di Lamboya, Wanokaka, dan Tana Righu. Di Tarung, sebagian rumah menyimpan pusaka keramat dan sebagian lain bertanggung jawab memutuskan kapan bulan itu dimulai.
Bagi pengunjung, inilah masa paling peka sepanjang tahun di kampung-kampung Waikabubak. Aturan ritualnya ketat, dan sebagian upacara serta area ditutup atau dibatasi. Jika berkunjung ke Tarung atau Praijing pada masa itu, datanglah hanya bersama pemandu setempat, mintalah izin sebelum masuk, dan ikuti arahannya. Tanggalnya berubah setiap tahun, jadi pastikan di tempat."""))

term("sandalwood-pony", {"en": "Sandalwood pony", "es": "Poni sandalwood", "id": "Kuda sandel"}, {"en": r"sandalwood pon(?:y|ies)", "es": r"ponis? sandalwood", "id": r"kuda sandel(?:wood)?|kuda sandalwood"}, ["sumba-horses-sandalwood-pony", "pasola-explained", "puru-kambera"], [], aka=["kuda Sandalwood", "kuda sandel", "ndara"],
 en=("The Sandalwood pony is the native horse breed of Sumba and Sumbawa: small, around 12 to 13 hands (roughly 120 to 130 cm), hardy and fast. It is named after the sandalwood the island once exported. Horses are part of the bridewealth, are sacrificed at funerals and are ridden in the Pasola and in races.",
 """The breed weighs around 250 kg and comes in almost any colour: bay, chestnut, black, grey, cream and pinto are all common. Breed descriptions highlight a fine head with small ears, a short muscular neck, a deep chest and good endurance, with Arabian blood in its lineage. Indonesia recognises the Sandalwood as one of its eight official native horse breeds, formally designated by a Ministry of Agriculture decree in 2014. The local name is ndara.
The name comes from sandalwood, cendana in Indonesian, the fragrant wood that made Sumba known to traders as Sandalwood Island. Horses and wood travelled together and both became prized exports: the first 98 horses were shipped in 1841, and more than 4,000 by 1846.
On the island the horse is far more than transport. It is a central part of the belis, the bridewealth that seals an alliance between clans. In the Marapu belief it carries the soul of the dead to the ancestors, which is why horses are sacrificed at funerals. And each February and March hundreds of riders gallop bareback in the Pasola. Horse racing, pacuan kuda, is the island's other great horse event.
Pure Sandalwood ponies are becoming harder to find, and the government has designated Matawai La Pawu district in East Sumba as a breeding source area to protect the line."""),
 es=("El poni sandalwood es la raza equina autóctona de Sumba y Sumbawa: pequeño, de unos 120 a 130 centímetros de alzada, resistente y veloz. Debe su nombre al sándalo que la isla exportaba antiguamente. Los caballos forman parte de la dote, se sacrifican en los funerales y se montan en la Pasola y en las carreras.",
 """La raza pesa unos 250 kilos y se da en casi cualquier capa: son corrientes el castaño, el alazán, el negro, el tordo, el crema y el pío. Las descripciones de la raza destacan una cabeza fina de orejas pequeñas, un cuello corto y musculoso, un pecho profundo y mucha resistencia, con sangre árabe en su linaje. Indonesia reconoce al sandalwood como una de sus ocho razas equinas autóctonas oficiales, designada por un decreto del Ministerio de Agricultura en 2014. Su nombre local es ndara.
El nombre viene del sándalo, cendana en indonesio, la madera aromática por la que los comerciantes conocían Sumba como la isla del Sándalo. Caballos y madera viajaban juntos y ambos se convirtieron en exportaciones codiciadas: los primeros 98 caballos se embarcaron en 1841, y en 1846 ya eran más de 4.000.
En la isla el caballo es mucho más que un medio de transporte. Es parte esencial del belis, la dote que sella la alianza entre clanes. En la creencia marapu lleva el alma del difunto hasta los antepasados, y por eso se sacrifican caballos en los funerales. Y cada febrero y marzo cientos de jinetes galopan a pelo en la Pasola. Las carreras, pacuan kuda, son la otra gran cita ecuestre.
Los ponis sandalwood de pura raza son cada vez más difíciles de encontrar, y el Gobierno ha declarado el distrito de Matawai La Pawu, en Sumba Oriental, zona de cría para proteger la línea."""),
 id=("Kuda sandel, atau kuda Sandalwood, adalah ras kuda asli Sumba dan Sumbawa: kecil, tingginya sekitar 120 sampai 130 cm, tangguh, dan cepat. Namanya diambil dari cendana, kayu yang dahulu diekspor dari pulau ini. Kuda menjadi bagian dari belis, dikurbankan pada pemakaman, serta ditunggangi dalam Pasola dan pacuan.",
 """Bobotnya sekitar 250 kg dan warnanya hampir apa saja: cokelat, merah bata, hitam, kelabu, krem, dan belang sama-sama lazim. Deskripsi ras menonjolkan kepala yang halus dengan telinga kecil, leher pendek berotot, dada dalam, dan daya tahan yang baik, dengan darah kuda Arab dalam garis keturunannya. Indonesia mengakui kuda sandel sebagai satu dari delapan rumpun kuda asli resmi, ditetapkan lewat keputusan Menteri Pertanian pada 2014. Nama setempatnya ndara.
Namanya berasal dari cendana (sandalwood), kayu harum yang membuat Sumba dikenal para pedagang sebagai Pulau Cendana. Kuda dan kayu diperdagangkan bersama dan sama-sama menjadi komoditas ekspor yang dicari: 98 ekor kuda pertama dikapalkan pada 1841, dan pada 1846 jumlahnya sudah lebih dari 4.000 ekor.
Di pulau ini kuda jauh lebih dari alat angkut. Kuda adalah bagian utama belis, mas kawin adat yang mengikat persekutuan antarkabihu. Dalam kepercayaan Marapu, kuda membawa arwah orang mati kepada leluhur, sehingga kuda dikurbankan pada pemakaman. Setiap Februari dan Maret, ratusan penunggang memacu kuda tanpa pelana dalam Pasola. Pacuan kuda menjadi perhelatan berkuda besar lainnya.
Kuda sandel murni kian sulit ditemukan, dan pemerintah telah menetapkan Kecamatan Matawai La Pawu di Sumba Timur sebagai wilayah sumber bibit untuk menjaga kemurniannya."""))

term("parang", "Parang", r"\bparang\b", ["sumba-travel-safety-health", "tarung-village", "pasola-2027-dates"], ["kabeala"], aka=["kabeala"], pron="PAH-rahng", nolink=("id",),
 en=("A parang is the long knife or machete that many Sumbanese men wear at the hip, especially in West and Southwest Sumba. It is worn with traditional dress and used as a farming tool. It is a cultural item, not a threat.",
 """Visitors often notice it on the first day: a man walking along the road with a long knife at his hip, and a smile. In Sumba the parang is part of how a man dresses and works. It is a working tool on the farm, and it completes traditional dress at ceremonies. A local guide can explain what a particular blade means to its owner.
Some blades are heirlooms. In Tarung, the ritual village in Waikabubak, certain houses keep sacred objects such as machetes, gongs and drums. In East Sumba the traditional blade is called a kabeala; Wikipedia describes it as about 50 to 60 cm long, with a hilt of buffalo horn and wood and a wooden sheath bound with woven strips, and notes its place in funeral dress.
The authorities do draw a line at large gatherings. In 2026 police in West Sumba banned drinking or selling alcohol and carrying machetes or other sharp weapons during the pajura boxing ritual and the Pasola.
For travellers the advice is the same as for any personal object: do not touch a man's parang or ask to handle it, and ask before photographing someone because of it. Most friction between visitors and villagers comes from misunderstanding, not hostility."""),
 es=("El parang es el cuchillo largo o machete que muchos hombres de Sumba llevan a la cadera, sobre todo en Sumba Occidental y Suroccidental. Se lleva con el traje tradicional y se usa como herramienta agrícola. Es un objeto cultural, no una amenaza.",
 """Muchos visitantes lo advierten el primer día: un hombre que camina por la carretera con un cuchillo largo a la cadera, y una sonrisa. En Sumba el parang forma parte de cómo viste y trabaja un hombre. Es una herramienta de trabajo en el campo y completa el traje tradicional en las ceremonias. Un guía local puede explicar qué significa una hoja concreta para su dueño.
Algunas hojas son reliquias. En Tarung, el pueblo ritual de Waikabubak, ciertas casas custodian objetos sagrados como machetes, gongs y tambores. En Sumba Oriental la hoja tradicional se llama kabeala; Wikipedia la describe como un arma de unos 50 a 60 centímetros, con empuñadura de cuerno de búfalo y madera y vaina de madera sujeta con tiras trenzadas, y señala su lugar en la indumentaria funeraria.
Las autoridades sí ponen límites en las grandes concentraciones. En 2026 la policía de Sumba Occidental prohibió beber o vender alcohol y llevar machetes u otras armas blancas durante el ritual de boxeo pajura y la Pasola.
Para el viajero vale el mismo consejo que con cualquier objeto personal: no tocar el parang de nadie ni pedir que se lo dejen, y pedir permiso antes de fotografiar a alguien por llevarlo. La mayoría de los roces entre visitantes y vecinos nacen de un malentendido, no de la hostilidad."""),
 id=("Parang adalah pisau panjang atau golok yang dibawa banyak laki-laki Sumba di pinggang, terutama di Sumba Barat dan Sumba Barat Daya. Parang dikenakan bersama busana adat dan dipakai sebagai alat bertani. Ini benda budaya, bukan ancaman.",
 """Pengunjung sering melihatnya sejak hari pertama: seorang laki-laki berjalan di tepi jalan dengan parang di pinggang, sambil tersenyum. Di Sumba, parang adalah bagian dari cara laki-laki berpakaian dan bekerja. Parang adalah alat kerja di ladang dan melengkapi busana adat dalam upacara. Pemandu setempat dapat menjelaskan arti sebilah parang bagi pemiliknya.
Sebagian parang adalah pusaka. Di Tarung, kampung ritual di Waikabubak, rumah-rumah tertentu menyimpan benda keramat seperti parang, gong, dan tambur. Di Sumba Timur bilah tradisional ini disebut kabeala; Wikipedia menggambarkannya sepanjang sekitar 50 sampai 60 cm, bergagang tanduk kerbau dan kayu, bersarung kayu yang diikat anyaman, serta mencatat tempatnya dalam busana upacara kematian.
Aparat tetap menarik garis pada keramaian besar. Pada 2026 polisi di Sumba Barat melarang minum atau menjual minuman keras serta membawa parang atau senjata tajam lain selama ritual tinju pajura dan Pasola.
Bagi pelancong, nasihatnya sama seperti terhadap benda pribadi lain: jangan menyentuh parang orang atau meminta memegangnya, dan mintalah izin sebelum memotret seseorang karena parangnya. Sebagian besar gesekan antara pengunjung dan warga lahir dari salah paham, bukan permusuhan."""))

term("sirih-pinang", {"en": "Sirih pinang (betel)", "es": "Sirih pinang (betel)", "id": "Sirih pinang"}, r"sirih pinang", ["sumbanese-food", "sumba-weddings-funerals-ceremonies", "sumba-markets"], ["who"], pron="SEE-rih PEE-nahng",
 en=("Sirih pinang is the chewing of betel leaf or catkin (sirih) with areca nut (pinang) and slaked lime. In Sumba, offering it is the basic gesture of respect to a guest, and a small bag bought at a market is the traditional gift when you enter a village. Visitors who do not chew are offered coffee instead.",
 """You will see red-stained smiles and red marks on the ground everywhere in Sumba. In the villages a guest is first offered a box of sirih pinang and a glass of very sweet coffee. In East Sumba the offering of betel to a guest is called pahappa, and the woven or carved box that holds it is a mbola happa.
The custom runs through every important occasion. Betel is shared at weddings and funerals, relatives bring it as an offering while a body is kept in the house, and it is placed at the graves of ancestors to ask for their blessing.
For travellers it is the easiest courtesy to get right. Markets in Waingapu and Waikabubak sell piles of betel leaf and areca nut beside bags of white lime paste. Buy a small bag, hand it to your host or the elder who receives you, sign the guest book and leave your donation. You are not obliged to chew: declining politely and accepting coffee is perfectly acceptable.
There is a health side. In 2003 the International Agency for Research on Cancer, part of the World Health Organization, classified betel quid, with or without tobacco, and areca nut itself as carcinogenic to humans. Respect the custom; you do not need to adopt the habit."""),
 es=("Sirih pinang es la costumbre de mascar hoja o fruto de betel (sirih) con nuez de areca (pinang) y cal apagada. En Sumba, ofrecerlo es el gesto básico de respeto hacia un invitado, y una bolsita comprada en el mercado es el regalo tradicional al entrar en un pueblo. A quien no masca se le ofrece café.",
 """En toda Sumba se ven sonrisas teñidas de rojo y manchas rojas en el suelo. En los pueblos, lo primero que se ofrece a un invitado es una caja de sirih pinang y un vaso de café muy dulce. En Sumba Oriental el ofrecimiento de betel a un invitado se llama pahappa, y la caja tejida o tallada que lo contiene, mbola happa.
La costumbre atraviesa todas las ocasiones importantes. El betel se comparte en bodas y funerales, los parientes lo llevan como ofrenda mientras el cuerpo permanece en la casa y se deposita en las tumbas de los antepasados para pedir su bendición.
Para el viajero es la cortesía más fácil de cumplir. En los mercados de Waingapu y Waikabubak se venden montones de hoja de betel y nuez de areca junto a bolsas de pasta blanca de cal. Basta con comprar una bolsita, entregársela al anfitrión o al anciano que recibe, firmar el libro de visitas y dejar el donativo. No hay obligación de mascar: rechazarlo con educación y aceptar un café es perfectamente correcto.
Hay también una cuestión de salud. En 2003 la Agencia Internacional para la Investigación del Cáncer, de la Organización Mundial de la Salud, clasificó como cancerígenos para el ser humano el betel mascado, con o sin tabaco, y la propia nuez de areca. Se puede respetar la costumbre sin adoptar el hábito."""),
 id=("Sirih pinang adalah kebiasaan mengunyah daun atau buah sirih bersama buah pinang dan kapur. Di Sumba, menyuguhkannya adalah tanda hormat paling dasar kepada tamu, dan sebungkus kecil yang dibeli di pasar menjadi buah tangan tradisional saat memasuki kampung. Tamu yang tidak mengunyah sirih akan disuguhi kopi.",
 """Senyum bernoda merah dan bercak merah di tanah terlihat di mana-mana di Sumba. Di kampung, tamu mula-mula disuguhi sekotak sirih pinang dan segelas kopi yang sangat manis. Di Sumba Timur, menyuguhkan sirih kepada tamu disebut pahappa, dan kotak anyaman atau ukiran tempat menyimpannya disebut mbola happa.
Kebiasaan ini hadir dalam setiap peristiwa penting. Sirih pinang dibagikan pada perkawinan dan pemakaman, dibawa kerabat sebagai persembahan selama jenazah disemayamkan di rumah, dan diletakkan di kubur leluhur untuk memohon berkat.
Bagi pelancong, inilah sopan santun yang paling mudah dipenuhi. Pasar di Waingapu dan Waikabubak menjual tumpukan daun sirih dan buah pinang di samping kantong kapur putih. Belilah sebungkus kecil, serahkan kepada tuan rumah atau tetua yang menyambut, isi buku tamu, dan tinggalkan donasi. Anda tidak wajib mengunyahnya: menolak dengan sopan lalu menerima kopi sepenuhnya dapat diterima.
Ada pula sisi kesehatannya. Pada 2003 Badan Internasional untuk Penelitian Kanker, bagian dari Organisasi Kesehatan Dunia, menggolongkan kunyahan sirih, dengan atau tanpa tembakau, serta buah pinang itu sendiri sebagai karsinogenik bagi manusia. Hormati adatnya; Anda tidak perlu ikut membiasakan diri."""))

term("kabupaten", {"en": "Kabupaten (regency)", "es": "Kabupaten (regencia)", "id": "Kabupaten"}, {"en": r"kabupaten|regenc(?:y|ies)", "es": r"kabupaten|regencias?", "id": r"kabupaten"}, ["sumba-facts-figures", "short-history-of-sumba", "east-sumba-regency", "west-sumba-regency", "southwest-sumba-regency", "central-sumba-regency"], [], pron="kah-boo-PAH-ten", nolink=("id",),
 en=("A kabupaten, in English a regency, is the Indonesian unit of local government below the province, headed by a regent (bupati). Sumba is divided into four: West Sumba, Southwest Sumba, Central Sumba and East Sumba, all in the province of East Nusa Tenggara. Each has its own capital and its own administration.",
 """The four regencies and their capitals are West Sumba (Sumba Barat, capital Waikabubak), Southwest Sumba (Sumba Barat Daya, capital Tambolaka), Central Sumba (Sumba Tengah, capital Waibakul) and East Sumba (Sumba Timur, capital Waingapu). These are the names you will see on road signs, tickets and official documents.
The map is recent. A law of 1958 created the regencies of East Sumba and West Sumba within the new province of East Nusa Tenggara, and in 1962 the old domain-based divisions were replaced by districts under state-appointed heads called camat. On 2 January 2007 two new regencies, Central Sumba and Southwest Sumba, were carved out of West Sumba. West Sumba is now the smallest of the four by area, at 737.42 km², and Central Sumba the smallest by population, with an estimated 94,187 inhabitants in mid-2025.
For travellers the regency matters more than it sounds. Official figures, from visitor counts to health data, are published regency by regency, and our news pages name the regency in every story. Our place pages give the regency of every beach, village and waterfall, and the two airports sit in different regencies: Tambolaka in Southwest Sumba and Waingapu in East Sumba, about 170 km and 4 to 5 hours apart by road."""),
 es=("Un kabupaten, en español regencia, es la unidad de gobierno local de Indonesia situada por debajo de la provincia y dirigida por un regente (bupati). Sumba se divide en cuatro: Sumba Occidental, Sumba Suroccidental, Sumba Central y Sumba Oriental, todas en la provincia de Nusa Tenggara Oriental. Cada una tiene su capital y su propia administración.",
 """Las cuatro regencias y sus capitales son Sumba Occidental (Sumba Barat, capital Waikabubak), Sumba Suroccidental (Sumba Barat Daya, capital Tambolaka), Sumba Central (Sumba Tengah, capital Waibakul) y Sumba Oriental (Sumba Timur, capital Waingapu). Los nombres indonesios son los que aparecen en las señales, los billetes y los documentos oficiales.
El mapa es reciente. Una ley de 1958 creó las regencias de Sumba Oriental y Sumba Occidental dentro de la nueva provincia de Nusa Tenggara Oriental, y en 1962 las antiguas divisiones basadas en los dominios tradicionales dieron paso a distritos dirigidos por jefes nombrados por el Estado, los camat. El 2 de enero de 2007 se separaron de Sumba Occidental dos regencias nuevas, Sumba Central y Sumba Suroccidental. Sumba Occidental es hoy la más pequeña de las cuatro por superficie, con 737,42 km², y Sumba Central la menos poblada, con unos 94.187 habitantes a mediados de 2025.
Para quien viaja, la regencia importa más de lo que parece. Las cifras oficiales, del número de visitantes a los datos de salud, se publican regencia a regencia, y nuestras noticias indican siempre de cuál se trata. Nuestras fichas de lugares indican la regencia de cada playa, pueblo y cascada, y los dos aeropuertos están en regencias distintas: Tambolaka en Sumba Suroccidental y Waingapu en Sumba Oriental, a unos 170 kilómetros y entre 4 y 5 horas por carretera."""),
 id=("Kabupaten adalah satuan pemerintahan daerah di bawah provinsi yang dipimpin seorang bupati. Pulau Sumba terbagi atas empat kabupaten: Sumba Barat, Sumba Barat Daya, Sumba Tengah, dan Sumba Timur, semuanya di Provinsi Nusa Tenggara Timur. Masing-masing memiliki ibu kota dan pemerintahan sendiri.",
 """Keempat kabupaten dan ibu kotanya adalah Sumba Barat (Waikabubak), Sumba Barat Daya (Tambolaka), Sumba Tengah (Waibakul), dan Sumba Timur (Waingapu). Nama-nama inilah yang tertera di papan jalan, tiket, dan dokumen resmi.
Peta ini tergolong baru. Undang-undang tahun 1958 membentuk Kabupaten Sumba Timur dan Sumba Barat dalam Provinsi Nusa Tenggara Timur yang baru berdiri, dan pada 1962 pembagian lama berdasarkan wilayah kerajaan digantikan kecamatan yang dipimpin camat yang diangkat negara. Pada 2 Januari 2007 dua kabupaten baru, Sumba Tengah dan Sumba Barat Daya, dimekarkan dari Sumba Barat. Kini Sumba Barat menjadi yang terkecil luasnya, 737,42 km², dan Sumba Tengah yang paling sedikit penduduknya, sekitar 94.187 jiwa pada pertengahan 2025.
Bagi pelancong, kabupaten lebih penting daripada kedengarannya. Angka resmi, dari jumlah kunjungan wisatawan hingga data kesehatan, diterbitkan per kabupaten, dan berita kami selalu menyebut kabupatennya. Halaman tempat kami mencantumkan kabupaten setiap pantai, kampung, dan air terjun. Dua bandara di pulau ini pun berada di kabupaten berbeda: Tambolaka di Sumba Barat Daya dan Waingapu di Sumba Timur, berjarak sekitar 170 km atau 4 sampai 5 jam perjalanan darat."""))

term("masyarakat-hukum-adat", {"en": "Masyarakat hukum adat (customary law community)", "es": "Masyarakat hukum adat (comunidad de derecho consuetudinario)", "id": "Masyarakat hukum adat"}, {"en": r"masyarakat hukum adat|customary law communit(?:y|ies)", "es": r"masyarakat hukum adat|comunidad(?:es)? de derecho consuetudinario", "id": r"masyarakat hukum adat"}, ["customary-adat-land-sumba-explained", "east-sumba-first-customary-land-certificate", "buying-land-property-sumba-foreigner"], ["hukum"],
 en=("Masyarakat hukum adat means customary law community: a group bound by descent or territory that still lives by its own customary rules, has its own institutions and controls a defined territory. Indonesian law recognises these communities and their communal right over land. In Sumba the term applies to the clans, the kabihu, and their elders.",
 """The Indonesian Constitution recognises these communities in Article 18B(2), which says the state recognises and respects customary law communities and their traditional rights as long as they are still alive and in line with the development of society and the unitary state. In practice a community is expected to show that it still functions: that it has elders or ritual leaders, a meeting house, rules that people follow and a territory with known limits. The legal site Hukumonline, summarising the land ministry's rules, describes such a community as a group of people with a shared cultural identity who have lived for generations in a particular area, tied by ancestry or common residence.
This matters in Sumba because much of the island is customary land held collectively by clans rather than under certificates. Recognition as a masyarakat hukum adat is the step that allows a community to register its communal right, the hak ulayat. Only a small part of that land has ever been mapped or registered.
In November 2026 East Sumba's deputy regent, Yonathan Hani, said three customary law communities were applying for communal certificates at the regency land office, and that one file was nearly complete.
For buyers and investors the lesson is caution: a seller's signature is not enough where a clan holds the land. Read our guide to customary land before any deal."""),
 es=("Masyarakat hukum adat significa comunidad de derecho consuetudinario: un grupo unido por el linaje o el territorio que sigue rigiéndose por sus propias normas tradicionales, tiene instituciones propias y controla un territorio definido. La ley indonesia reconoce a estas comunidades y su derecho colectivo sobre la tierra. En Sumba el término se aplica a los clanes, los kabihu, y a sus ancianos.",
 """La Constitución indonesia reconoce a estas comunidades en el artículo 18B(2), según el cual el Estado reconoce y respeta a las comunidades de derecho consuetudinario y sus derechos tradicionales mientras sigan vivas y sean acordes con la evolución de la sociedad y con el Estado unitario. En la práctica, una comunidad tiene que demostrar que sigue funcionando: que tiene ancianos o jefes rituales, una casa de reunión, normas que la gente cumple y un territorio de límites conocidos. El portal jurídico Hukumonline, que resume la normativa del ministerio de tierras, la describe como un grupo de personas con una identidad cultural común que vive desde hace generaciones en una zona concreta, unido por la ascendencia o por la residencia compartida.
En Sumba esto importa porque buena parte de la isla es tierra consuetudinaria, en manos colectivas de los clanes y no amparada por certificados. El reconocimiento como masyarakat hukum adat es el paso que permite a una comunidad registrar su derecho colectivo, el hak ulayat. Solo una pequeña parte de esa tierra se ha cartografiado o inscrito alguna vez.
En noviembre de 2026 el vicerregente de Sumba Oriental, Yonathan Hani, afirmó que tres comunidades de derecho consuetudinario estaban solicitando certificados colectivos en la oficina de tierras de la regencia y que uno de los expedientes estaba casi completo.
Para compradores e inversores, la lección es la prudencia: la firma de un vendedor no basta cuando la tierra es de un clan. Antes de cualquier operación conviene leer nuestra guía sobre la tierra consuetudinaria."""),
 id=("Masyarakat hukum adat adalah kelompok yang terikat oleh garis keturunan atau wilayah, masih hidup menurut aturan adatnya sendiri, memiliki lembaga sendiri, dan menguasai wilayah tertentu. Hukum Indonesia mengakui masyarakat ini beserta hak bersamanya atas tanah. Di Sumba istilah ini merujuk pada kabihu dan para tetuanya.",
 """Undang-Undang Dasar 1945 mengakui masyarakat ini dalam Pasal 18B ayat (2): negara mengakui dan menghormati kesatuan masyarakat hukum adat beserta hak tradisionalnya sepanjang masih hidup dan sesuai dengan perkembangan masyarakat serta prinsip Negara Kesatuan Republik Indonesia. Dalam praktik, sebuah komunitas perlu menunjukkan bahwa ia masih berfungsi: memiliki tetua atau pemimpin ritual, rumah pertemuan, aturan yang ditaati, dan wilayah dengan batas yang diketahui. Hukumonline, yang merangkum aturan kementerian pertanahan, menyebutnya sekelompok orang yang memiliki identitas budaya yang sama, hidup turun-temurun di wilayah tertentu, dan terikat oleh asal-usul leluhur atau kesamaan tempat tinggal.
Hal ini penting di Sumba karena sebagian besar pulau merupakan tanah adat yang dikuasai bersama oleh kabihu, bukan tanah bersertifikat. Pengakuan sebagai masyarakat hukum adat adalah langkah yang memungkinkan sebuah komunitas mendaftarkan hak bersamanya, yakni hak ulayat. Baru sebagian kecil tanah itu yang pernah dipetakan atau didaftarkan.
Pada November 2026 Wakil Bupati Sumba Timur Yonathan Hani menyatakan tiga masyarakat hukum adat sedang mengajukan sertifikat komunal di kantor pertanahan kabupaten, dan satu berkas hampir lengkap.
Bagi pembeli dan investor, pelajarannya adalah kehati-hatian: tanda tangan seorang penjual tidak cukup bila tanahnya milik kabihu. Bacalah panduan kami tentang tanah adat sebelum bertransaksi."""))

term("hak-ulayat", "Hak ulayat", r"hak ulayat|tanah ulayat", ["customary-adat-land-sumba-explained", "east-sumba-first-customary-land-certificate", "buying-land-property-sumba-foreigner"], ["hukum"],
 en=("Hak ulayat is the collective right of a customary law community over its territory: the land, water, plants and animals within it. Indonesia's Basic Agrarian Law of 1960 recognises the right as long as it still exists in fact. In Sumba it is held by clans through their elders, and only a small part of such land has been registered.",
 """The concept comes from the Basic Agrarian Law of 1960, known as UUPA. Its Article 3 recognises hak ulayat as long as, in reality, it still exists, and provided it does not conflict with national law. The legal site Hukumonline defines tanah ulayat, the land itself, as the shared land of the members of the customary law community concerned.
For decades the right was acknowledged on paper but rarely recorded. That is slowly changing. For land outside forests, the Ministry of Agrarian Affairs and Spatial Planning (ATR/BPN) issued Regulation 14 of 2024 on the administration and registration of ulayat land, and between 2023 and September 2025 it issued 57 management-right titles to 18 communities nationwide.
In Sumba the holders are the clans, the kabihu, acting through their elders and senior houses. In November 2026 three East Sumba communities were applying for communal titles, the first step of this kind on the island reported by our newsroom.
Why it matters to outsiders: a plot offered for sale may sit on land a clan regards as its own, whatever an individual seller says. Overlapping claims are a main cause of land disputes. Anyone buying or leasing should check the status with the land office, ask who the customary holders are and get independent legal advice. Our land guides explain the steps."""),
 es=("El hak ulayat es el derecho colectivo de una comunidad de derecho consuetudinario sobre su territorio: la tierra, el agua, las plantas y los animales que contiene. La Ley Agraria Básica de Indonesia, de 1960, lo reconoce siempre que siga existiendo de hecho. En Sumba lo ejercen los clanes a través de sus ancianos, y solo una pequeña parte de esas tierras está registrada.",
 """El concepto procede de la Ley Agraria Básica de 1960, conocida como UUPA. Su artículo 3 reconoce el hak ulayat mientras, en la realidad, siga existiendo y siempre que no entre en conflicto con la legislación nacional. El portal jurídico Hukumonline define el tanah ulayat, la tierra en sí, como la tierra común de los miembros de la comunidad de derecho consuetudinario de que se trate.
Durante décadas el derecho se reconocía sobre el papel, pero rara vez se inscribía. Eso está cambiando poco a poco. Para las tierras situadas fuera de los bosques, el Ministerio de Asuntos Agrarios y Ordenación del Territorio (ATR/BPN) aprobó el Reglamento 14 de 2024 sobre la administración y el registro de la tierra ulayat, y entre 2023 y septiembre de 2025 expidió 57 títulos de derecho de gestión a 18 comunidades de todo el país.
En Sumba los titulares son los clanes, los kabihu, que actúan a través de sus ancianos y de sus casas principales. En noviembre de 2026 tres comunidades de Sumba Oriental estaban solicitando títulos colectivos, el primer paso de este tipo en la isla del que ha informado nuestra redacción.
Por qué importa a los de fuera: una parcela en venta puede estar en tierras que un clan considera suyas, diga lo que diga el vendedor. Las reclamaciones superpuestas son una de las principales causas de litigio. Quien compre o arriende debe comprobar la situación en la oficina de tierras, preguntar quiénes son los titulares tradicionales y buscar asesoramiento jurídico independiente. Nuestras guías sobre la tierra explican los pasos."""),
 id=("Hak ulayat adalah hak bersama masyarakat hukum adat atas wilayahnya: tanah, air, tumbuhan, dan hewan di dalamnya. Undang-Undang Pokok Agraria 1960 mengakui hak ini sepanjang menurut kenyataannya masih ada. Di Sumba hak ini dipegang kabihu melalui para tetuanya, dan baru sebagian kecil tanahnya yang terdaftar.",
 """Konsep ini bersumber dari Undang-Undang Nomor 5 Tahun 1960 tentang Peraturan Dasar Pokok-Pokok Agraria (UUPA). Pasal 3 mengakui hak ulayat sepanjang menurut kenyataannya masih ada dan tidak bertentangan dengan peraturan perundang-undangan nasional. Hukumonline mendefinisikan tanah ulayat sebagai tanah bersama para warga masyarakat hukum adat yang bersangkutan.
Selama puluhan tahun hak ini diakui di atas kertas, tetapi jarang dicatat. Keadaan itu perlahan berubah. Untuk tanah di luar kawasan hutan, Kementerian Agraria dan Tata Ruang/Badan Pertanahan Nasional (ATR/BPN) menerbitkan Peraturan Nomor 14 Tahun 2024 tentang penyelenggaraan administrasi dan pendaftaran tanah ulayat, dan sejak 2023 hingga September 2025 menerbitkan 57 sertifikat hak pengelolaan bagi 18 komunitas di seluruh Indonesia.
Di Sumba pemegangnya adalah kabihu, melalui para tetua dan rumah-rumah induknya. Pada November 2026 tiga komunitas di Sumba Timur mengajukan sertifikat komunal, langkah pertama semacam ini di pulau ini yang diberitakan redaksi kami.
Mengapa ini penting bagi orang luar: sebidang tanah yang ditawarkan bisa saja berada di atas tanah yang dianggap milik sebuah kabihu, apa pun kata penjualnya. Klaim yang tumpang-tindih adalah salah satu penyebab utama sengketa tanah. Siapa pun yang hendak membeli atau menyewa perlu memeriksa statusnya di kantor pertanahan, menanyakan siapa pemegang adatnya, dan meminta nasihat hukum independen. Panduan pertanahan kami menjelaskan langkah-langkahnya."""))

term("wita", "WITA", r"\bWITA\b", ["sumba-facts-figures", "sumba-sunsets-sunrises", "how-to-get-to-sumba-from-bali"], ["time"], aka=["Waktu Indonesia Tengah", "Central Indonesia Time"], pron="WEE-tah", nolink=("id",),
 en=("WITA stands for Waktu Indonesia Tengah, Central Indonesia Time, which is UTC+8. Sumba, like Bali and the rest of East Nusa Tenggara, is on WITA all year: Indonesia does not use daylight saving time. Every time on The Sumba Times is given in WITA.",
 """Indonesia has three time zones. WIB, Western Indonesia Time, is UTC+7 and covers Sumatra, Java, including Jakarta and Yogyakarta, and the west and centre of Kalimantan. WITA, UTC+8, covers Bali, West and East Nusa Tenggara, Sulawesi and the south, east and north of Kalimantan. WIT, Eastern Indonesia Time, is UTC+9 and covers Maluku and Papua. The present arrangement has applied since 1 January 1988.
For a trip to Sumba this has a few practical consequences. Flying from Jakarta, Surabaya or Yogyakarta you lose an hour going east; from Bali, Lombok, Labuan Bajo, Kupang or Makassar there is no change. Flight times on tickets are always local to each airport. From Europe, Sumba is 7 hours ahead of mainland Spain in winter and 6 in summer.
Days are short and regular this close to the equator. In the dry months sunset falls between about 17:45 and 18:00 WITA, which is why our guides tell you to plan each day around the light and to be off unlit roads before dark.
On this site, publication times, ferry and flight schedules and sunrise tables are all in WITA unless we say otherwise. In Indonesian the time is written with a full stop, as in pukul 06.00 WITA."""),
 es=("WITA son las siglas de Waktu Indonesia Tengah, la hora de Indonesia central, que equivale a UTC+8. Sumba, como Bali y el resto de Nusa Tenggara Oriental, se rige por WITA todo el año: Indonesia no cambia la hora en verano. Todas las horas de The Sumba Times se dan en WITA.",
 """Indonesia tiene tres husos horarios. WIB, la hora de Indonesia occidental, es UTC+7 y abarca Sumatra, Java, con Yakarta y Yogyakarta, y el oeste y el centro de Kalimantan. WITA, UTC+8, cubre Bali, Nusa Tenggara Occidental y Oriental, Célebes y el sur, el este y el norte de Kalimantan. WIT, la hora de Indonesia oriental, es UTC+9 y rige en las Molucas y Papúa. El reparto actual está en vigor desde el 1 de enero de 1988.
Para un viaje a Sumba esto tiene algunas consecuencias prácticas. Volando desde Yakarta, Surabaya o Yogyakarta se pierde una hora al ir hacia el este; desde Bali, Lombok, Labuan Bajo, Kupang o Makassar no hay cambio. Las horas de los billetes son siempre las locales de cada aeropuerto. Sumba va 7 horas por delante de la España peninsular en invierno y 6 en verano, 14 por delante de Ciudad de México, 13 de Bogotá y 11 de Buenos Aires.
Tan cerca del ecuador, los días son cortos y regulares. En los meses secos el sol se pone entre las 17:45 y las 18:00 WITA, aproximadamente, y por eso nuestras guías aconsejan organizar cada jornada según la luz y dejar las carreteras sin alumbrado antes de que anochezca.
En este sitio, las horas de publicación, los horarios de ferris y vuelos y las tablas de amanecer están en WITA salvo que se indique otra cosa."""),
 id=("WITA adalah singkatan dari Waktu Indonesia Tengah, yakni UTC+8. Sumba, seperti Bali dan seluruh Nusa Tenggara Timur, memakai WITA sepanjang tahun karena Indonesia tidak mengenal waktu musim panas. Semua jam di The Sumba Times ditulis dalam WITA.",
 """Indonesia memiliki tiga zona waktu. WIB, Waktu Indonesia Barat, adalah UTC+7 dan mencakup Sumatra, Jawa, termasuk Jakarta dan Yogyakarta, serta Kalimantan Barat dan Kalimantan Tengah. WITA, UTC+8, mencakup Bali, Nusa Tenggara Barat dan Timur, Sulawesi, serta Kalimantan Selatan, Timur, dan Utara. WIT, Waktu Indonesia Timur, adalah UTC+9 dan berlaku di Maluku dan Papua. Pembagian ini berlaku sejak 1 Januari 1988.
Untuk perjalanan ke Sumba, ada beberapa akibat praktisnya. Terbang dari Jakarta, Surabaya, atau Yogyakarta berarti jam maju satu jam; dari Bali, Lombok, Labuan Bajo, Kupang, atau Makassar tidak ada perubahan. Jam pada tiket selalu mengikuti waktu setempat di tiap bandara.
Sedekat ini dengan khatulistiwa, panjang hari pendek dan nyaris tetap. Pada bulan-bulan kemarau matahari terbenam antara sekitar pukul 17.45 dan 18.00 WITA. Karena itu panduan kami menyarankan agar setiap hari disusun mengikuti cahaya dan agar pengunjung sudah meninggalkan jalan tanpa penerangan sebelum gelap.
Di situs ini, jam terbit berita, jadwal feri dan penerbangan, serta tabel matahari terbit semuanya dalam WITA kecuali disebutkan lain. Penulisannya memakai titik, misalnya pukul 06.00 WITA."""))

term("ojek", "Ojek", r"\bojeks?\b", ["getting-around-sumba", "sumba-on-a-budget", "tambolaka-town", "waingapu-town"], ["kbbi_ojek", "spice"], pron="OH-jek", nolink=("id",),
 en=("An ojek is a motorbike taxi: you ride pillion behind the driver and agree the fare before setting off. In Sumba, where there are no Grab or Gojek cars and no metered taxis, ojeks cover the short hops in and around the towns. They can also be hired by the day.",
 """The Indonesian dictionary KBBI defines ojek as a bicycle or motorbike hired out by carrying the passenger on the back. Elsewhere in Indonesia the old-style ojek has largely been displaced by ride-hailing apps; in Sumba it has not, because the apps do not operate here as they do in Bali.
In Waingapu ojeks are cheap and plentiful, and in Waikabubak and Tambolaka they are easy to find. They are how many travellers reach places just outside town: the villages of Tarung and Prailiu, a viewpoint for sunset, or the last unpaved stretch to a waterfall such as Tanggedu, where the final 3 km or so across the savanna are done on foot or by ojek. Where a shared minibus drops you at a junction, as at Bondo Kodi, an ojek usually covers the rest.
Agree the price before you get on, every time. Travellers' reports put the ride from Tambolaka airport to town at around IDR 10,000, but prices vary and change. Ask your accommodation what a fair fare is.
Helmets are compulsory in Indonesia, so ask for one, and keep rides short. For a full day of sightseeing, most visitors hire a car with a driver."""),
 es=("Un ojek es un mototaxi: el pasajero viaja de paquete detrás del conductor y el precio se acuerda antes de salir. En Sumba, donde no hay coches de Grab ni de Gojek ni taxis con taxímetro, los ojek cubren los trayectos cortos dentro y alrededor de las ciudades. También pueden contratarse por días.",
 """El diccionario indonesio KBBI define ojek como la bicicleta o la moto que se alquila llevando al pasajero en la parte de atrás. En el resto de Indonesia las aplicaciones de transporte han desplazado en buena medida al ojek de siempre; en Sumba no, porque aquí esas aplicaciones no funcionan como en Bali.
En Waingapu los ojek son baratos y abundantes, y en Waikabubak y Tambolaka es fácil encontrarlos. Así llegan muchos viajeros a los lugares que quedan a las afueras: los pueblos de Tarung y Prailiu, un mirador para el atardecer o el último tramo sin asfaltar hasta una cascada como Tanggedu, donde los 3 kilómetros finales por la sabana se hacen a pie o en ojek. Cuando un minibús compartido deja al viajero en un cruce, como en Bondo Kodi, el resto suele hacerse en ojek.
El precio se acuerda antes de subir, siempre. Según cuentan los viajeros, el trayecto del aeropuerto de Tambolaka a la ciudad ronda las 10.000 rupias, pero los precios varían y cambian. Lo mejor es preguntar en el alojamiento cuál es una tarifa justa.
El casco es obligatorio en Indonesia, así que conviene pedirlo y limitarse a trayectos cortos. Para un día entero de visitas, la mayoría de los viajeros contrata un coche con conductor."""),
 id=("Ojek adalah sepeda motor sewaan dengan pengemudi: penumpang membonceng di belakang dan ongkosnya disepakati sebelum berangkat. Di Sumba, yang tidak memiliki layanan mobil Grab atau Gojek maupun taksi berargo, ojek melayani perjalanan pendek di dalam dan sekitar kota. Ojek juga bisa disewa harian.",
 """KBBI mendefinisikan ojek sebagai sepeda atau sepeda motor yang ditambangkan dengan cara memboncengkan penumpang atau penyewanya. Di banyak daerah lain ojek pangkalan sebagian besar tergeser aplikasi transportasi daring; di Sumba tidak, karena aplikasi itu tidak beroperasi di sini seperti di Bali.
Di Waingapu ojek murah dan banyak, sedangkan di Waikabubak dan Tambolaka mudah ditemukan. Dengan ojek banyak pelancong mencapai tempat di pinggir kota: Kampung Tarung dan Prailiu, bukit untuk menikmati senja, atau ruas terakhir yang belum beraspal menuju air terjun seperti Tanggedu, yang 3 km terakhirnya melintasi sabana ditempuh dengan berjalan kaki atau naik ojek. Jika angkutan umum menurunkan penumpang di persimpangan, misalnya di Bondo Kodi, sisanya biasanya dilanjutkan dengan ojek.
Sepakati ongkos sebelum naik, setiap kali. Menurut cerita para pelancong, ongkos dari Bandara Tambolaka ke kota sekitar Rp 10.000, tetapi harga beragam dan berubah. Tanyakan tarif yang wajar kepada penginapan.
Helm wajib dipakai, jadi mintalah helm dan batasi untuk jarak dekat. Untuk berkeliling seharian, sebagian besar pengunjung menyewa mobil dengan sopir."""))

term("travel", {"en": "Travel (shared car)", "es": "Travel (coche compartido)", "id": "Travel (mobil angkutan bersama)"}, {"en": r"\"travel\"|shared \"travel\"|shared cars?", "es": r"\"travel\"|coches? compartidos?", "id": r"mobil travel|\"travel\""}, ["getting-around-sumba", "sumba-on-a-budget", "tambolaka-town", "waingapu-town"], ["spice"], nolink=("en", "es", "id"),
 en=("In Indonesia a travel is a shared car or minibus that carries passengers between towns for a fixed price per seat. In Sumba, travel cars and buses link Tambolaka, Waikabubak and Waingapu, taking roughly 4 to 6 hours across the island. They are cheap but slow, leave when full and do not go to beaches or villages.",
 """The word is English but the meaning is Indonesian. The Spice Route End, a guide to road transport in Indonesia, describes travel as private cars run by independent drivers or, more often, by agencies, usually with door-to-door pick-up or departure from a set point in town, slightly more expensive than a bus and a little faster.
In Sumba the main route is the road across the island. Daily buses and travel cars run between Tambolaka and Waingapu via Waikabubak in roughly 4 to 6 hours, and between Waikabubak and Waingapu in about 3 to 4 hours. Older listings show minibuses from Waitabula (Tambolaka) to Waikabubak in about 1.5 hours and to Bondo Kodi in about an hour. Fares are in the tens of thousands of rupiah.
The limits are clear. Departures depend on passengers, so times are approximate, and the routes follow the main road only. Most of what visitors come for, the lagoons, beaches, waterfalls and traditional villages, lies off it.
Use a travel car to move between your bases, for example from a few days in the west to a few days in the east, and arrange a car with driver for the days of sightseeing. Your accommodation can usually tell you where the cars leave from and what a seat costs."""),
 es=("En Indonesia, un travel es un coche o minibús compartido que lleva pasajeros de una ciudad a otra por un precio fijo por plaza. En Sumba, los travel y los autobuses unen Tambolaka, Waikabubak y Waingapu y tardan entre 4 y 6 horas en cruzar la isla. Son baratos pero lentos, salen cuando se llenan y no llegan a las playas ni a los pueblos.",
 """La palabra es inglesa, pero el significado es indonesio. The Spice Route End, una guía del transporte por carretera en Indonesia, describe los travel como coches particulares gestionados por conductores independientes o, más a menudo, por agencias, que suelen recoger a domicilio o salir de un punto fijo de la ciudad, algo más caros que el autobús y un poco más rápidos.
En Sumba la ruta principal es la carretera que cruza la isla. Cada día hay autobuses y travel entre Tambolaka y Waingapu por Waikabubak, en unas 4 a 6 horas, y entre Waikabubak y Waingapu en unas 3 o 4. Listados más antiguos recogen minibuses desde Waitabula (Tambolaka) a Waikabubak en hora y media y a Bondo Kodi en una hora. Las tarifas son de decenas de miles de rupias.
Los límites están claros. Las salidas dependen de los pasajeros, así que los horarios son aproximados, y las rutas siguen solo la carretera principal. Casi todo lo que atrae al visitante, las lagunas, las playas, las cascadas y los pueblos tradicionales, queda fuera de ella.
Lo sensato es usar un travel para cambiar de base, por ejemplo de unos días en el oeste a unos días en el este, y contratar un coche con conductor para las jornadas de visitas. En el alojamiento suelen saber de dónde salen los coches y cuánto cuesta la plaza."""),
 id=("Travel adalah mobil atau minibus angkutan bersama yang membawa penumpang antarkota dengan tarif tetap per kursi. Di Sumba, mobil travel dan bus menghubungkan Tambolaka, Waikabubak, dan Waingapu dengan waktu tempuh sekitar 4 sampai 6 jam melintasi pulau. Murah tetapi lambat, berangkat setelah penuh, dan tidak sampai ke pantai atau kampung.",
 """Katanya dari bahasa Inggris, tetapi maknanya khas Indonesia. The Spice Route End, panduan angkutan darat di Indonesia, menggambarkan travel sebagai mobil pribadi yang dijalankan sopir perorangan atau, lebih sering, agen perjalanan, biasanya menjemput ke alamat atau berangkat dari titik tertentu di kota, sedikit lebih mahal daripada bus dan sedikit lebih cepat.
Di Sumba rute utamanya adalah jalan lintas pulau. Setiap hari ada bus dan mobil travel antara Tambolaka dan Waingapu lewat Waikabubak, sekitar 4 sampai 6 jam, serta antara Waikabubak dan Waingapu sekitar 3 sampai 4 jam. Catatan lama menyebut angkutan dari Waitabula (Tambolaka) ke Waikabubak sekitar 1,5 jam dan ke Bondo Kodi sekitar satu jam. Tarifnya puluhan ribu rupiah.
Keterbatasannya jelas. Keberangkatan bergantung pada penumpang sehingga jamnya kira-kira saja, dan rutenya hanya mengikuti jalan utama. Sebagian besar tujuan pengunjung, seperti laguna, pantai, air terjun, dan kampung adat, berada di luar jalur itu.
Pakailah travel untuk berpindah basis, misalnya dari beberapa hari di barat ke beberapa hari di timur, lalu sewa mobil dengan sopir untuk hari-hari berkeliling. Penginapan biasanya tahu dari mana mobil berangkat dan berapa tarif per kursi."""))

term("bemo", "Bemo", r"\bbemos?\b", ["getting-around-sumba", "waikelo-sawah-waterfall", "wanokaka-beach", "waingapu-town"], ["kbbi_bemo", "spice"], pron="BEH-mo", nolink=("id",),
 en=("A bemo is a small public minibus that runs a set route in and around a town. In Sumba, bemos work the main streets of Waingapu and the roads out of Waikabubak and Tambolaka, and they will drop you at a junction on request. They are cheap and slow.",
 """The word began as a contraction of becak motor, a motorised rickshaw, and the Indonesian dictionary KBBI still lists that sense first, followed by a three-wheeled public vehicle and then a four-wheeled public passenger vehicle that is not a bus. In some regions it became the everyday word for a public minibus; the generic term is angkot.
In Sumba you will meet bemos in three situations. In Waingapu they rattle along Jalan Ahmad Yani, and one heading east can drop you near the turn-off for Bukit Persaudaraan. On the Tambolaka to Waikabubak road, public minibuses can leave you at the turn-off for Waikelo Sawah waterfall, from where it is about 1.5 km on foot. And from Waikabubak, bemos run to the Wanokaka junction, where local ojeks take over.
Fares are low. A 2017 travel account paid around IDR 5,000 for the bus to Wanokaka, a price that will have risen since. Have small notes ready, tell the driver where you want to get off and ask the fare before boarding if you are unsure.
Bemos are slow, leave when full and do not reach most beaches, waterfalls or villages. They suit unhurried travellers on a budget; for a tight itinerary, use a car with a driver."""),
 es=("Un bemo es un pequeño minibús público que cubre una ruta fija dentro y alrededor de una ciudad. En Sumba, los bemos recorren las calles principales de Waingapu y las carreteras que salen de Waikabubak y Tambolaka, y paran en un cruce si se les pide. Son baratos y lentos.",
 """La palabra nació como abreviatura de becak motor, un triciclo motorizado, y el diccionario indonesio KBBI sigue recogiendo ese sentido en primer lugar, seguido del de vehículo público de tres ruedas y del de vehículo público de pasajeros de cuatro ruedas que no es un autobús. En algunas regiones pasó a ser la palabra corriente para el minibús público; el término genérico es angkot.
En Sumba el viajero se cruza con los bemos en tres situaciones. En Waingapu traquetean por Jalan Ahmad Yani, y uno que vaya hacia el este puede parar cerca del desvío de Bukit Persaudaraan. En la carretera de Tambolaka a Waikabubak, los minibuses públicos dejan en el desvío de la cascada de Waikelo Sawah, desde donde queda alrededor de kilómetro y medio a pie. Y desde Waikabubak hay bemos hasta el cruce de Wanokaka, donde toman el relevo los ojek de la zona.
Las tarifas son bajas. Un relato de viaje de 2017 pagó unas 5.000 rupias por el autobús a Wanokaka, un precio que habrá subido desde entonces. Conviene llevar billetes pequeños, decir al conductor dónde se quiere bajar y, en caso de duda, preguntar el precio antes de subir.
Los bemos son lentos, salen cuando se llenan y no llegan a la mayoría de las playas, cascadas o pueblos. Son para viajeros sin prisa y con poco presupuesto; con un itinerario apretado, lo adecuado es un coche con conductor."""),
 id=("Bemo adalah angkutan umum kecil yang melayani rute tetap di dalam dan sekitar kota. Di Sumba, bemo melintasi jalan utama Waingapu serta jalan keluar dari Waikabubak dan Tambolaka, dan bisa menurunkan penumpang di persimpangan bila diminta. Murah, tetapi lambat.",
 """Kata ini bermula dari singkatan becak motor, dan KBBI masih mencantumkan arti itu lebih dulu, disusul kendaraan umum beroda tiga, lalu kendaraan bermotor angkutan penumpang umum dalam kota yang bukan bus dan beroda empat. Di sejumlah daerah, bemo menjadi sebutan sehari-hari untuk angkutan kota; istilah umumnya angkot.
Di Sumba, bemo dijumpai dalam tiga keadaan. Di Waingapu, bemo melaju di Jalan Ahmad Yani, dan yang menuju timur bisa menurunkan penumpang di dekat simpang ke Bukit Persaudaraan. Di jalan Tambolaka-Waikabubak, angkutan umum dapat menurunkan penumpang di simpang Air Terjun Waikelo Sawah, dari sana sekitar 1,5 km berjalan kaki. Dari Waikabubak ada bemo ke simpang Wanokaka, lalu perjalanan dilanjutkan dengan ojek setempat.
Ongkosnya murah. Sebuah catatan perjalanan tahun 2017 menyebut sekitar Rp 5.000 untuk bus ke Wanokaka, harga yang tentu sudah naik. Siapkan uang kecil, sampaikan kepada sopir di mana Anda ingin turun, dan bila ragu tanyakan ongkos sebelum naik.
Bemo lambat, berangkat setelah penuh, dan tidak menjangkau sebagian besar pantai, air terjun, atau kampung. Bemo cocok bagi pelancong santai beranggaran terbatas; untuk rencana perjalanan yang padat, pakailah mobil dengan sopir."""))

term("warung", "Warung", r"\bwarungs?\b", ["sumbanese-food", "sumba-travel-costs", "sumba-on-a-budget"], ["kbbi_warung"], pron="WAH-roong", nolink=("id",),
 en=("A warung is a small, simple place that sells food, drinks or everyday goods. In Sumba it is where most people eat out: a meal costs roughly IDR 20,000 to 50,000. Outside the towns warungs are few and many close by about 19:00.",
 """The Indonesian dictionary KBBI defines warung as a place that sells food, drinks, groceries and the like, and gives kedai as a synonym.
For travellers in Sumba the warung is the basis of an affordable trip. Day to day the island is cheap: meals at a local warung cost roughly IDR 20,000 to 50,000 (about USD 1 to 3), while tourist restaurants and hotels cost much more. Some serve daun ubi, cassava-leaf soup, so routinely that it comes free with the meal. Halal food is easiest to find in Muslim-run warungs, Padang restaurants and Javanese stalls in the towns; pork is common in Christian and Marapu households and at feasts, and dog meat is served at a few local places, though not on general menus.
The practical limit is distance and time. There are few places to eat outside Waingapu, Waikabubak and Tambolaka, many warungs close by about 19:00, and some beaches, such as Marosi, have no warungs or toilets at all. On Sundays many shops close. Pack water, snacks and lunch for long drives, and eat early in the evening.
Carry small notes and expect to pay in cash: ATMs are rare outside the main towns."""),
 es=("Un warung es un local pequeño y sencillo que vende comida, bebida o artículos de uso diario. En Sumba es donde come fuera la mayoría de la gente: una comida cuesta entre 20.000 y 50.000 rupias. Fuera de las ciudades hay pocos, y muchos cierran hacia las 19:00.",
 """El diccionario indonesio KBBI define warung como el lugar donde se venden comida, bebidas, comestibles y cosas parecidas, y da kedai como sinónimo.
Para quien viaja por Sumba, el warung es la base de un viaje asequible. En el día a día la isla es barata: comer en un warung local cuesta entre 20.000 y 50.000 rupias (de 1 a 3 dólares, aproximadamente), mientras que los restaurantes turísticos y los hoteles salen mucho más caros. En algunos, la sopa de hojas de yuca, daun ubi, es tan corriente que se sirve gratis con la comida. La comida halal es más fácil de encontrar en los warung regentados por musulmanes, en los restaurantes de cocina de Padang y en los puestos javaneses de las ciudades; el cerdo es habitual en los hogares cristianos y marapu y en las fiestas, y en algunos locales se sirve carne de perro, aunque no figura en las cartas generales.
El límite práctico son las distancias y los horarios. Fuera de Waingapu, Waikabubak y Tambolaka hay pocos sitios donde comer, muchos warung cierran hacia las 19:00 y en algunas playas, como Marosi, no hay ni warung ni aseos. Los domingos cierran muchas tiendas. Para los trayectos largos conviene llevar agua, algo de picar y el almuerzo, y cenar temprano.
Conviene llevar billetes pequeños y contar con pagar en efectivo: fuera de las ciudades principales apenas hay cajeros."""),
 id=("Warung adalah tempat sederhana yang menjual makanan, minuman, atau kebutuhan sehari-hari. Di Sumba, warung menjadi tempat makan sebagian besar orang: sekali makan berharga sekitar Rp 20.000 sampai Rp 50.000. Di luar kota jumlahnya sedikit dan banyak yang tutup sekitar pukul 19.00.",
 """KBBI mendefinisikan warung sebagai tempat menjual makanan, minuman, kelontong, dan sebagainya, dengan kedai sebagai padanannya.
Bagi pelancong di Sumba, warung adalah dasar perjalanan yang terjangkau. Sehari-hari pulau ini murah: makan di warung setempat berkisar Rp 20.000 sampai Rp 50.000, sedangkan restoran wisata dan hotel jauh lebih mahal. Di sebagian warung, sayur daun ubi begitu lazim sehingga disajikan gratis bersama makanan. Makanan halal paling mudah ditemukan di warung milik pedagang muslim, rumah makan Padang, dan warung Jawa di kota; daging babi lazim di rumah tangga Kristen dan Marapu serta pada pesta adat, dan daging anjing dijual di beberapa warung setempat walau tidak ada di menu umum.
Batas praktisnya adalah jarak dan jam buka. Tempat makan di luar Waingapu, Waikabubak, dan Tambolaka sedikit, banyak warung tutup sekitar pukul 19.00, dan sebagian pantai, seperti Marosi, sama sekali tidak memiliki warung atau toilet. Pada hari Minggu banyak toko tutup. Bawalah air minum, camilan, dan bekal makan siang untuk perjalanan jauh, dan makan malamlah lebih awal.
Siapkan uang pecahan kecil dan bersiaplah membayar tunai: ATM jarang ada di luar kota-kota utama."""))

term("pasar", {"en": "Pasar (market)", "es": "Pasar (mercado)", "id": "Pasar"}, r"\bpasar\b", ["sumba-markets", "sumbanese-food", "waingapu-town", "waikabubak-town"], ["kbbi_pasar"], pron="PAH-sar", nolink=("id",),
 en=("Pasar is the Indonesian word for market, the place where people buy and sell. The markets travellers can rely on in Sumba are the permanent town markets: Pasar Inpres in the Matawai area of Waingapu and Pasar Waikabubak, often called Pasar Baru, in West Sumba. Both are busiest in the morning.",
 """The Indonesian dictionary KBBI defines pasar simply as a place where people buy and sell. On maps and signs the word comes before the name, as in Pasar Inpres or Pasar Baru.
Pasar Inpres in Waingapu is the main market of East Sumba and, according to a 2025 study by researchers at the local Wira Wacana Christian University, one of the largest in the regency. It trades every day: vegetables, herbs, chillies, spices, fish, betel nut and sometimes woven textiles or ceremonial items. In Waikabubak, Pasar Waikabubak is a working market rather than a tourist attraction, with produce, dried fish, live chickens, betel nut, household goods and sometimes local cloth.
Go early: both markets are best in the morning.
A market is also where a visit to a village begins. A small bag of sirih pinang, betel and areca nut, is the traditional gift when you enter a traditional village, alongside the donation in the guest book, and the market is where you buy it.
Manners are simple: ask before photographing people, buy something if you spend time at a stall, even if it is only a little fruit and carry small notes."""),
 es=("Pasar es la palabra indonesia para mercado, el lugar donde se compra y se vende. Los mercados con los que puede contar el viajero en Sumba son los permanentes de las ciudades: el Pasar Inpres, en la zona de Matawai de Waingapu, y el Pasar Waikabubak, llamado a menudo Pasar Baru, en Sumba Occidental. Los dos tienen más actividad por la mañana.",
 """El diccionario indonesio KBBI define pasar, sin más, como el lugar donde la gente compra y vende. En los mapas y las señales la palabra precede al nombre, como en Pasar Inpres o Pasar Baru.
El Pasar Inpres de Waingapu es el principal mercado de Sumba Oriental y, según un estudio de 2025 de investigadores de la Universidad Cristiana Wira Wacana, uno de los mayores de la regencia. Abre todos los días: verduras, hierbas, guindillas, especias, pescado, nuez de betel y, a veces, tejidos o artículos ceremoniales. En Waikabubak, el Pasar Waikabubak es un mercado de diario más que una atracción turística, con productos frescos, pescado seco, pollos vivos, nuez de betel, menaje y, en ocasiones, telas locales.
Hay que ir temprano: los dos mercados están en su mejor momento por la mañana.
En el mercado empieza también la visita a un pueblo. Una bolsita de sirih pinang, betel y nuez de areca, es el regalo tradicional al entrar en un pueblo tradicional, junto con el donativo del libro de visitas, y es en el mercado donde se compra.
Las normas son sencillas: pedir permiso antes de fotografiar a la gente, comprar algo si uno se detiene un rato en un puesto, aunque sea un poco de fruta y llevar billetes pequeños."""),
 id=("Pasar adalah tempat orang berjual beli. Pasar yang bisa diandalkan pelancong di Sumba adalah pasar tetap di kota: Pasar Inpres di kawasan Matawai, Waingapu, dan Pasar Waikabubak, yang kerap disebut Pasar Baru, di Sumba Barat. Keduanya paling ramai pada pagi hari.",
 """KBBI mendefinisikan pasar sebagai tempat orang berjual beli. Bagi pengunjung dari luar negeri, kata ini termasuk yang pertama perlu dikenali karena tertera di peta dan papan nama.
Pasar Inpres di Waingapu adalah pasar utama Sumba Timur dan, menurut penelitian tahun 2025 oleh peneliti Universitas Kristen Wira Wacana Sumba, termasuk yang terbesar di kabupaten itu. Pasar ini buka setiap hari dan menjual sayur, bumbu, cabai, rempah, ikan, sirih pinang, dan kadang kain tenun atau perlengkapan upacara. Di Waikabubak, Pasar Waikabubak adalah pasar harian, bukan objek wisata, dengan hasil bumi, ikan kering, ayam hidup, sirih pinang, perabot rumah tangga, dan sesekali kain setempat.
Datanglah pagi-pagi: kedua pasar paling hidup pada pagi hari.
Pasar juga menjadi awal kunjungan ke kampung. Sebungkus kecil sirih pinang adalah buah tangan tradisional saat memasuki kampung adat, di samping donasi di buku tamu, dan di pasarlah barang itu dibeli.
Tata kramanya sederhana: mintalah izin sebelum memotret orang, belilah sesuatu jika berlama-lama di sebuah lapak walau hanya sedikit buah, dan siapkan uang pecahan kecil."""))

term("kain", {"en": "Kain (cloth)", "es": "Kain (tela)", "id": "Kain"}, r"\bkain\b", ["sumba-ikat-weaving-where-to-buy", "sumba-weddings-funerals-ceremonies", "prailiu-village"], ["kbbi_kain", "textiles"], pron="KAH-een", nolink=("id",),
 en=("Kain is the Indonesian word for cloth. In Sumba it usually means a hand-woven textile: the men's hinggi, the women's lau or a narrower shoulder cloth. These cloths mark status, are exchanged at weddings and funerals and are the island's best-known craft.",
 """The Indonesian dictionary KBBI defines kain as something woven from cotton thread and, more broadly, as woven material for clothing or other purposes. In shops and villages you will hear it constantly: kain tenun for woven cloth, kain ikat for cloth patterned by tying and dyeing the threads.
Sumba's main cloths have their own names. The hinggi is the large rectangular men's cloth, made in pairs, one for the hips and one for the shoulder. The lau is the women's tubular skirt, often decorated with supplementary warp, beads or shells. Tiara are narrow cloths used as shoulder cloths or headbands.
What makes them matter is how they move. Wikipedia's article on the textiles of Sumba calls them the currency of traditional ceremonial exchange: finely folded cloths answer the horses, buffalo and gold of the bridewealth, and at funerals they are given and used to wrap the dead. In traditional households each stage of the work is opened with prayers.
For visitors, two courtesies. If your host offers you a cloth or sarong to wear at a ceremony, accept it; wearing woven cloth at important events is appreciated. And if you buy, buy slowly: ask who made it, with which dyes and over how many months, and expect to pay for that time."""),
 es=("Kain es la palabra indonesia para tela. En Sumba suele referirse a un tejido hecho a mano: el hinggi de los hombres, el lau de las mujeres o una tela más estrecha para el hombro. Estas telas señalan el rango, se intercambian en bodas y funerales y son la artesanía más conocida de la isla.",
 """El diccionario indonesio KBBI define kain como lo que se teje con hilo de algodón y, en sentido amplio, como el tejido destinado a la ropa o a otros usos. En tiendas y pueblos se oye sin parar: kain tenun para la tela tejida, kain ikat para la que lleva el dibujo atado y teñido en los hilos.
Las principales telas de Sumba tienen nombre propio. El hinggi es la gran tela rectangular masculina, que se hace por parejas, una para las caderas y otra para el hombro. El lau es la falda tubular femenina, a menudo decorada con urdimbre suplementaria, cuentas o conchas. Las tiara son telas estrechas que se usan sobre el hombro o como cinta para la cabeza.
Lo que les da importancia es cómo circulan. El artículo de Wikipedia sobre los tejidos de Sumba las llama la moneda del intercambio ceremonial tradicional: las telas finamente dobladas responden a los caballos, búfalos y oro de la dote, y en los funerales se regalan y envuelven a los difuntos. En los hogares tradicionales, cada fase del trabajo se abre con oraciones.
Para el visitante, dos cortesías. Si el anfitrión ofrece una tela o un sarong para llevar en una ceremonia, hay que aceptarlo: vestir tela tejida en las ocasiones importantes se agradece. Y si se compra, que sea despacio: preguntando quién la hizo, con qué tintes y en cuántos meses, y contando con pagar ese tiempo."""),
 id=("Kain adalah barang tenunan untuk pakaian atau keperluan lain. Di Sumba kata ini biasanya merujuk pada kain tenun tangan: hinggi untuk laki-laki, lau untuk perempuan, atau kain selendang yang lebih sempit. Kain menandai kedudukan, dipertukarkan pada perkawinan dan pemakaman, dan menjadi kerajinan paling terkenal dari pulau ini.",
 """KBBI mendefinisikan kain sebagai barang yang ditenun dari benang kapas dan, lebih luas, barang tenunan untuk pakaian atau untuk maksud lain. Di toko dan kampung kata ini terus terdengar: kain tenun, kain ikat, kain adat.
Kain utama Sumba memiliki nama sendiri. Hinggi adalah kain besar persegi panjang untuk laki-laki, dibuat sepasang, satu untuk pinggang dan satu untuk bahu. Lau adalah sarung tabung untuk perempuan, kerap dihias lungsin tambahan, manik-manik, atau kerang. Tiara adalah kain sempit yang dipakai sebagai selendang atau ikat kepala.
Yang membuatnya penting adalah peredarannya. Artikel Wikipedia tentang tekstil Sumba menyebut kain sebagai alat tukar dalam pertukaran adat: kain yang dilipat rapi menjadi balasan atas kuda, kerbau, dan emas dalam belis, dan pada pemakaman kain diberikan serta dipakai membungkus jenazah. Di rumah tangga tradisional, setiap tahap pengerjaannya dibuka dengan doa.
Bagi pengunjung, ada dua sopan santun. Jika tuan rumah menawarkan kain atau sarung untuk dikenakan dalam upacara, terimalah; mengenakan kain tenun pada acara penting dihargai. Jika membeli, lakukan dengan sabar: tanyakan siapa pembuatnya, pewarna apa yang dipakai, dan berapa bulan pengerjaannya, lalu bayarlah sepadan dengan waktu itu."""))

term("tenun", {"en": "Tenun (weaving)", "es": "Tenun (tejido)", "id": "Tenun"}, r"\btenun\b", ["sumba-ikat-weaving-where-to-buy", "prailiu-village", "pau-village", "kaliuda-village"], ["kbbi_tenun", "textiles"], pron="tuh-NOON", nolink=("id",),
 en=("Tenun is the Indonesian word for weaving and for hand-woven cloth. In Sumba, tenun is women's work done on backstrap looms, and tenun ikat, in which the pattern is tied and dyed into the threads first, is the island's signature craft. The best-known weaving villages are in East Sumba.",
 """The Indonesian dictionary KBBI defines tenun as a craft product in the form of cloth made from thread, such as cotton or silk, and lists tenun ikat as a weaving technique found in Nusa Tenggara. Kain tenun means woven cloth.
In Sumba the weaver sits on a mat with the loom tied around her waist, sliding the threads through by hand and knocking them into place with a wooden beater. Before that come the spinning, the tying of the pattern and repeated dyeing with indigo and morinda root, which is why a large natural-dye cloth takes months.
Two techniques dominate. Ikat produces the large figurative men's cloths, the hinggi. Pahikung, a supplementary warp technique, produces raised patterns, especially on women's skirts, and is a separate skill.
Where to see it: Prailiu and Lambanapu on the edge of Waingapu, Pau and Rende near Melolo, and Kaliuda in the south-east, known for naturally dyed cloth in morinda red and indigo. In Prailiu weaving is usually not shown on Sundays. Kawangu, east of Waingapu, is known for cheaper synthetic-dye cloth, useful for comparing colours and prices.
Buy directly from the weavers when you can: it is the fairest way to keep the craft alive."""),
 es=("Tenun es la palabra indonesia para el tejido artesanal y para la tela tejida a mano. En Sumba es un trabajo de mujeres que se hace en telares de cintura, y el tenun ikat, en el que el dibujo se ata y se tiñe antes en los hilos, es la artesanía emblemática de la isla. Los pueblos de tejedoras más conocidos están en Sumba Oriental.",
 """El diccionario indonesio KBBI define tenun como un producto artesanal en forma de tela hecha con hilo, de algodón o seda por ejemplo, y recoge tenun ikat como una técnica de tejido propia de Nusa Tenggara. Kain tenun significa tela tejida.
En Sumba la tejedora se sienta en una estera con el telar sujeto a la cintura, pasa los hilos a mano y los aprieta con un batidor de madera. Antes vienen el hilado, el atado del dibujo y los teñidos sucesivos con índigo y raíz de morinda, y por eso una tela grande con tintes naturales lleva meses.
Dominan dos técnicas. El ikat da las grandes telas figurativas de los hombres, los hinggi. El pahikung, una técnica de urdimbre suplementaria, crea dibujos en relieve, sobre todo en las faldas de las mujeres, y es un oficio aparte.
Dónde verlo: Prailiu y Lambanapu, a las afueras de Waingapu; Pau y Rende, cerca de Melolo, y Kaliuda, en el sureste, conocido por sus telas de tintes naturales en rojo de morinda e índigo. En Prailiu no se suele tejer ante los visitantes los domingos. Kawangu, al este de Waingapu, es conocido por sus telas más baratas de tinte sintético, útiles para comparar colores y precios.
Siempre que se pueda, es mejor comprar directamente a las tejedoras: es la forma más justa de mantener vivo el oficio."""),
 id=("Tenun adalah hasil kerajinan berupa kain yang dibuat dari benang, sekaligus sebutan untuk pekerjaan menenun. Di Sumba, menenun adalah pekerjaan perempuan dengan alat tenun gedogan, dan tenun ikat, yang motifnya lebih dulu diikat dan dicelup pada benang, menjadi kerajinan khas pulau ini. Kampung penenun paling dikenal berada di Sumba Timur.",
 """KBBI mendefinisikan tenun sebagai hasil kerajinan yang berupa bahan (kain) yang dibuat dari benang, misalnya kapas atau sutra, dan mencatat tenun ikat sebagai salah satu teknik bertenun yang terdapat di Nusa Tenggara.
Di Sumba penenun duduk di atas tikar dengan alat tenun terikat di pinggang, memasukkan benang dengan tangan, lalu merapatkannya dengan bilah kayu. Sebelum itu ada pemintalan, pengikatan motif, dan pencelupan berulang dengan nila serta akar mengkudu. Itulah sebabnya selembar kain besar berpewarna alam memakan waktu berbulan-bulan.
Ada dua teknik utama. Ikat menghasilkan kain besar bermotif figuratif untuk laki-laki, yakni hinggi. Pahikung, teknik lungsin tambahan, menghasilkan motif timbul, terutama pada sarung perempuan, dan merupakan keterampilan tersendiri.
Tempat melihatnya: Prailiu dan Lambanapu di pinggir Waingapu, Pau dan Rende di dekat Melolo, serta Kaliuda di tenggara yang dikenal dengan kain berpewarna alam merah mengkudu dan nila. Di Prailiu kegiatan menenun biasanya tidak diperlihatkan pada hari Minggu. Kawangu, di timur Waingapu, dikenal dengan kain berpewarna sintetis yang lebih murah, berguna untuk membandingkan warna dan harga.
Sebisa mungkin belilah langsung dari penenunnya: itulah cara paling adil untuk menjaga kerajinan ini tetap hidup."""))

term("sabana", {"en": "Sabana (savanna)", "es": "Sabana", "id": "Sabana"}, {"en": r"sabana|savannas?", "es": r"sabanas?", "id": r"sabana"}, ["east-sumba-regency", "puru-kambera", "wairinding-hill", "best-time-to-visit-sumba"], ["kbbi_sabana"], aka=["savana"], pron="sah-BAH-nah", nolink=("id", "es"),
 en=("Sabana is the Indonesian word for savanna: open grassland with scattered trees. It is the landscape of East Sumba, golden for most of the year and green for a few months after the rains. The hills around Waingapu, such as Wairinding, and the plain of Puru Kambera are the best-known places to see it.",
 """The Indonesian dictionary KBBI defines sabana as grassland with trees on it. In Sumba the word describes most of the eastern half of the island, which is far drier than the west. The north-east, from Waingapu up to the northern cape of Tanjung Sasar, is the driest and most thinly populated corner: brown and dusty after months without rain, then a soft lime green from about March, after the monsoon.
That seasonal change decides what you will photograph. In the dry season, roughly May to September and into November in the east, the hills are gold. In the rainy season, roughly December to March, they turn a brilliant green.
The classic viewpoints are close to Waingapu. Wairinding Hill is about 30 to 45 minutes west of the airport, and Bukit Tanau and Bukit Persaudaraan are nearer still. At Puru Kambera, about 45 to 60 minutes away on the north coast, horses roam free on the savanna above a calm beach. The walk to Tanggedu waterfall crosses about 3 km of open grassland.
Practical points: the savanna has almost no shade and the sun this close to the equator is fierce, so go at sunrise or late afternoon and carry water, a hat and sun protection."""),
 es=("Sabana, la misma palabra en indonesio y en español, designa una pradera abierta con árboles dispersos. Es el paisaje de Sumba Oriental, dorado casi todo el año y verde unos meses después de las lluvias. Las colinas de los alrededores de Waingapu, como Wairinding, y la llanura de Puru Kambera son los lugares más conocidos para verla.",
 """El diccionario indonesio KBBI define sabana como una pradera con árboles. En Sumba la palabra describe casi toda la mitad oriental de la isla, mucho más seca que la occidental. El noreste, de Waingapu al cabo septentrional de Tanjung Sasar, es el rincón más árido y menos poblado: pardo y polvoriento tras meses sin lluvia, y de un verde lima suave a partir de marzo, después del monzón.
Ese cambio de estación decide lo que se va a fotografiar. En la estación seca, más o menos de mayo a septiembre y hasta noviembre en el este, las colinas son doradas. En la de lluvias, de diciembre a marzo aproximadamente, se vuelven de un verde intenso.
Los miradores clásicos quedan cerca de Waingapu. La colina de Wairinding está a unos 30 o 45 minutos al oeste del aeropuerto, y Bukit Tanau y Bukit Persaudaraan, aún más cerca. En Puru Kambera, a unos 45 o 60 minutos por la costa norte, los caballos andan sueltos por la sabana sobre una playa tranquila. El camino a la cascada de Tanggedu cruza unos 3 kilómetros de pradera abierta.
En lo práctico: la sabana casi no tiene sombra y el sol, tan cerca del ecuador, aprieta, así que conviene ir al amanecer o a última hora de la tarde y llevar agua, sombrero y protección solar."""),
 id=("Sabana adalah padang rumput yang ditumbuhi pepohonan. Inilah bentang alam Sumba Timur, keemasan hampir sepanjang tahun dan hijau selama beberapa bulan setelah hujan. Perbukitan di sekitar Waingapu, seperti Wairinding, dan padang Puru Kambera adalah tempat paling dikenal untuk menikmatinya.",
 """KBBI mendefinisikan sabana sebagai padang rumput yang ada pepohonannya. Di Sumba kata ini menggambarkan hampir seluruh belahan timur pulau, yang jauh lebih kering daripada bagian barat. Wilayah timur laut, dari Waingapu hingga Tanjung Sasar di ujung utara, adalah sudut paling kering dan paling jarang penduduknya: cokelat dan berdebu setelah berbulan-bulan tanpa hujan, lalu hijau muda sejak sekitar Maret, selepas musim hujan.
Pergantian musim itu menentukan apa yang akan Anda potret. Pada musim kemarau, kira-kira Mei sampai September dan hingga November di timur, perbukitan berwarna emas. Pada musim hujan, kira-kira Desember sampai Maret, perbukitan berubah hijau cerah.
Titik pandang utamanya dekat dari Waingapu. Bukit Wairinding berjarak sekitar 30 sampai 45 menit di barat bandara, sedangkan Bukit Tanau dan Bukit Persaudaraan lebih dekat lagi. Di Puru Kambera, sekitar 45 sampai 60 menit ke arah pantai utara, kuda merumput bebas di sabana di atas pantai yang tenang. Jalan kaki menuju Air Terjun Tanggedu melintasi sekitar 3 km padang terbuka.
Catatan praktis: sabana nyaris tanpa naungan dan matahari sedekat ini dengan khatulistiwa sangat terik, jadi datanglah saat matahari terbit atau sore hari dan bawalah air minum, topi, serta pelindung matahari."""))

term("tanjung", {"en": "Tanjung (cape)", "es": "Tanjung (cabo)", "id": "Tanjung"}, r"\btanjung\b", ["east-sumba-regency", "bawana-beach", "ratenggaro-village"], ["kbbi_tanjung"], pron="TAHN-joong", nolink=("id",),
 en=("Tanjung is the Indonesian word for a cape or headland: land that juts out into the sea. On maps of Sumba it appears before the name, as in Tanjung Sasar, the northern cape of East Sumba, or Tanjung Radar, the headland beside Bawana beach in the south-west.",
 """The Indonesian dictionary KBBI defines tanjung as land, or the end of a range of hills, that projects into the sea or a lake. It is one of a handful of geographic words worth learning before you read a map of Sumba, together with pantai (beach), bukit (hill), air terjun (waterfall) and danau (lake).
Two capes appear in our guides. Tanjung Sasar is the northern tip of East Sumba; the country between it and Waingapu is the driest and most thinly populated corner of the island, brown after months without rain and green from about March. Tanjung Radar is the headland in Kodi, Southwest Sumba, next to Bawana beach, also written Mbawana, where a famous sea arch stood on a narrow cape until it collapsed in November 2020.
Headlands matter in Sumba for a second reason: some of the island's most striking traditional villages stand on them. Ratenggaro, in Kodi, has its tall-roofed houses and stone tombs on a headland above the sea at a river mouth, facing Wainyapu on the other side of the estuary.
For travellers, a tanjung usually means the end of the road. Go with a driver who knows the way, carry water and ask about the state of the track in the rainy season."""),
 es=("Tanjung es la palabra indonesia para cabo o promontorio: la tierra que se adentra en el mar. En los mapas de Sumba aparece delante del nombre, como en Tanjung Sasar, el cabo septentrional de Sumba Oriental, o Tanjung Radar, el promontorio contiguo a la playa de Bawana, en el suroeste.",
 """El diccionario indonesio KBBI define tanjung como la tierra, o el extremo de una cadena de colinas, que se adentra en el mar o en un lago. Es una de las pocas palabras geográficas que conviene aprender antes de leer un mapa de Sumba, junto con pantai (playa), bukit (colina), air terjun (cascada) y danau (lago).
En nuestras guías aparecen dos cabos. Tanjung Sasar es el extremo norte de Sumba Oriental; el territorio que lo separa de Waingapu es el rincón más seco y menos poblado de la isla, pardo tras meses sin lluvia y verde a partir de marzo. Tanjung Radar es el promontorio de Kodi, en Sumba Suroccidental, junto a la playa de Bawana, escrita también Mbawana, donde un famoso arco de roca se alzaba sobre un cabo estrecho hasta que se derrumbó en noviembre de 2020.
Los promontorios importan en Sumba por otra razón: sobre ellos se levantan algunos de los pueblos tradicionales más llamativos de la isla. Ratenggaro, en Kodi, tiene sus casas de tejado alto y sus tumbas de piedra en un promontorio sobre el mar, en la desembocadura de un río, frente a Wainyapu, al otro lado del estuario.
Para el viajero, un tanjung suele ser el final de la carretera. Conviene ir con un conductor que conozca el camino, llevar agua y, en época de lluvias, informarse del estado de la pista."""),
 id=("Tanjung adalah tanah atau ujung pegunungan yang menganjur ke laut. Di peta Sumba kata ini mendahului nama tempat, seperti Tanjung Sasar, ujung utara Sumba Timur, atau Tanjung Radar, tanjung di samping Pantai Bawana di barat daya.",
 """KBBI mendefinisikan tanjung sebagai tanah (ujung) atau pegunungan yang menganjur ke laut atau ke danau. Bagi pengunjung dari luar negeri, ini satu dari segelintir kata geografi yang berguna dikenali sebelum membaca peta Sumba, bersama pantai, bukit, air terjun, dan danau.
Dua tanjung muncul dalam panduan kami. Tanjung Sasar adalah ujung utara Sumba Timur; wilayah di antara tanjung itu dan Waingapu adalah sudut paling kering dan paling jarang penduduknya di pulau ini, cokelat setelah berbulan-bulan tanpa hujan dan hijau sejak sekitar Maret. Tanjung Radar adalah tanjung di Kodi, Sumba Barat Daya, di samping Pantai Bawana, juga ditulis Mbawana, tempat lengkung batu terkenal berdiri di tanjung sempit hingga runtuh pada November 2020.
Tanjung penting di Sumba karena alasan lain: beberapa kampung adat paling memukau berdiri di atasnya. Ratenggaro di Kodi memiliki rumah beratap tinggi dan kubur batu di tanjung di atas laut, di muara sungai, berhadapan dengan Wainyapu di seberang muara.
Bagi pelancong, tanjung biasanya berarti ujung jalan. Pergilah bersama sopir yang mengenal jalan, bawa air minum, dan pada musim hujan tanyakan dulu keadaan jalannya."""))

term("pantai", {"en": "Pantai (beach)", "es": "Pantai (playa)", "id": "Pantai"}, r"\bpantai\b", ["beaches-lagoons-waterfalls", "walakiri-beach", "marosi-beach", "londa-lima-beach"], [], pron="PAHN-tai", nolink=("id",),
 en=("Pantai is the Indonesian word for beach or coast. On signs and maps in Sumba it comes before the name: Pantai Walakiri, Pantai Marosi, Pantai Kalala. Most of the island's beaches are undeveloped, with few or no facilities.",
 """Knowing the word helps as soon as you leave the airport, because road signs, drivers and map apps use the Indonesian names. Pantai Londa Lima, north-west of Waingapu, is also called Pantai Kuta by locals because it lies in Kuta village; it has nothing to do with Kuta in Bali. Pantai Wanokaka is also written Wanukaka, and Pantai Watu Parunu is also written Watu Parunnu. If one spelling returns nothing on a map, try the other.
Sumba's beaches differ sharply by coast. The north coast near Waingapu is calmer: Londa Lima is the town's nearest white-sand beach and Walakiri is known for its dwarf mangroves, best seen as silhouettes at low tide around sunset. The south and west coasts face the Indian Ocean, with surf and stronger swell in the dry season at beaches such as Marosi and Kerewe, and many of them have strong currents.
What most beaches share is the absence of services. Marosi, for example, has no warungs or toilets on the beach, and there are generally no lifeguards. Entrance is often free or a token amount, and a small parking contribution may be asked.
Bring water, food, sun protection and cash, take your rubbish back with you, and ask locally about currents and safe places to swim before going in. Our place pages give the road distance, the nearest airport and the best time of day for each beach."""),
 es=("Pantai es la palabra indonesia para playa o costa. En las señales y los mapas de Sumba va delante del nombre: Pantai Walakiri, Pantai Marosi, Pantai Kalala. La mayoría de las playas de la isla están sin urbanizar y tienen pocos servicios o ninguno.",
 """Conocer la palabra ayuda nada más salir del aeropuerto, porque las señales, los conductores y las aplicaciones de mapas usan los nombres indonesios. Pantai Londa Lima, al noroeste de Waingapu, recibe también el nombre de Pantai Kuta porque está en la aldea de Kuta; no tiene nada que ver con la Kuta de Bali. Pantai Wanokaka se escribe también Wanukaka, y Pantai Watu Parunu, Watu Parunnu. Si una grafía no da resultados en el mapa, conviene probar con la otra.
Las playas de Sumba cambian mucho de una costa a otra. La costa norte, cerca de Waingapu, es más tranquila: Londa Lima es la playa de arena blanca más cercana a la ciudad y Walakiri es conocida por sus manglares enanos, que lucen más como siluetas con marea baja al atardecer. Las costas sur y oeste dan al océano Índico, con olas y más mar de fondo en la estación seca en playas como Marosi y Kerewe, y en muchas hay corrientes fuertes.
Lo que casi todas comparten es la falta de servicios. En Marosi, por ejemplo, no hay warung ni aseos en la playa, y por lo general no hay socorristas. La entrada suele ser gratuita o simbólica, y a veces se pide una pequeña aportación por aparcar.
Hay que llevar agua, comida, protección solar y efectivo, recoger la basura y preguntar a la gente del lugar por las corrientes y las zonas seguras antes de bañarse. Nuestras fichas indican la distancia por carretera, el aeropuerto más cercano y la mejor hora del día para cada playa."""),
 id=("Pantai adalah tepi laut, dan di Sumba kata ini mendahului nama tempat di papan jalan dan peta: Pantai Walakiri, Pantai Marosi, Pantai Kalala. Sebagian besar pantai di pulau ini belum dikembangkan, dengan fasilitas yang minim atau tidak ada sama sekali.",
 """Mengenal nama setempat berguna sejak keluar dari bandara, karena papan jalan, sopir, dan aplikasi peta memakainya. Pantai Londa Lima, di barat laut Waingapu, juga disebut Pantai Kuta oleh warga karena berada di Desa Kuta; tidak ada hubungannya dengan Kuta di Bali. Pantai Wanokaka juga ditulis Wanukaka, dan Pantai Watu Parunu juga ditulis Watu Parunnu. Jika satu ejaan tidak muncul di peta, cobalah ejaan lainnya.
Pantai di Sumba sangat berbeda antara satu pesisir dan pesisir lain. Pesisir utara di dekat Waingapu lebih tenang: Londa Lima adalah pantai pasir putih terdekat dari kota, dan Walakiri dikenal dengan bakau kerdilnya saat senja dan air surut. Pesisir selatan dan barat menghadap Samudra Hindia, dengan ombak selancar dan alun yang lebih kuat pada musim kemarau, misalnya di Marosi dan Kerewe, dan banyak di antaranya berarus kuat.
Yang sama pada hampir semua pantai adalah ketiadaan layanan. Di Marosi, misalnya, tidak ada warung atau toilet di pantai, dan umumnya tidak ada penjaga pantai. Masuknya sering gratis atau sangat murah, dan kadang diminta uang parkir kecil.
Bawalah air minum, makanan, pelindung matahari, dan uang tunai, bawa pulang sampah Anda, dan tanyakan kepada warga tentang arus serta tempat yang aman sebelum berenang. Halaman tempat kami mencantumkan jarak lewat jalan, bandara terdekat, dan waktu terbaik untuk tiap pantai."""))

term("air-terjun", {"en": "Air terjun (waterfall)", "es": "Air terjun (cascada)", "id": "Air terjun"}, r"\bair terjun\b", ["beaches-lagoons-waterfalls", "lapopu-waterfall", "tanggedu-waterfall", "waimarang-waterfall"], [], pron="AH-eer tuhr-JOON", nolink=("id",),
 en=("Air terjun is the Indonesian term for waterfall; literally, air means water and terjun means to plunge. On maps and signs in Sumba it comes before the name, as in Air Terjun Lapopu or Air Terjun Tanggedu. Most of the island's waterfalls involve a walk and are at their fullest in the rainy season.",
 """The five waterfalls with their own pages on this site show how different they are. Lapopu, in Wanokaka, West Sumba, and Matayangu, in Central Sumba, are forest falls reached on foot; Matayangu means a proper jungle trek. Waikelo Sawah, between Tambolaka and Waikabubak, is a river that flows out of a cave, about 1.5 km on foot from the main road if you arrive by public minibus. In the east, Tanggedu is not a single tall waterfall but a system of cascades and natural pools where rivers cut through a limestone canyon, reached by a walk of around 3 km across the savanna, or an ojek ride. Waimarang is a modest fall feeding a wide natural pool of clear turquoise water, inland from Melolo.
Season changes everything. In the rainy season, roughly December to March, waterfalls are at their fullest and the hills are green, but forest trails become muddy and slippery and roads can be cut. In the dry season the trails are easier.
Wear proper shoes with good grip and carry water. There are no lifeguards, so ask locally before swimming. On the longer walks, such as Matayangu, where the trail is not marked, hire a local guide. Each page gives the walking time and the nearest airport."""),
 es=("Air terjun es el término indonesio para cascada; literalmente, air significa agua y terjun, precipitarse. En los mapas y las señales de Sumba va delante del nombre, como en Air Terjun Lapopu o Air Terjun Tanggedu. Casi todas las cascadas de la isla exigen caminar y llevan más agua en la estación de lluvias.",
 """Las cinco cascadas con ficha propia en este sitio muestran lo distintas que son. Lapopu, en Wanokaka, Sumba Occidental, y Matayangu, en Sumba Central, son saltos de bosque a los que se llega a pie; Matayangu supone una verdadera caminata por la selva. Waikelo Sawah, entre Tambolaka y Waikabubak, es un río que sale de una cueva, a alrededor de kilómetro y medio a pie de la carretera principal si se llega en minibús público. En el este, Tanggedu no es un único salto alto, sino un sistema de cascadas y pozas naturales donde los ríos atraviesan un cañón de caliza, al que se llega tras caminar unos 3 kilómetros por la sabana o en ojek. Waimarang es un salto modesto que alimenta una amplia poza natural de agua turquesa y transparente, tierra adentro desde Melolo.
La estación lo cambia todo. En la de lluvias, de diciembre a marzo aproximadamente, las cascadas van en su máximo caudal y las colinas están verdes, pero los senderos del bosque se vuelven embarrados y resbaladizos y las carreteras pueden quedar cortadas. En la seca los senderos son más fáciles.
Hay que llevar calzado con buen agarre y agua. No hay socorristas, así que conviene preguntar a la gente del lugar antes de bañarse. En las caminatas largas, como la de Matayangu, donde el sendero no está señalizado, hay que contratar un guía local. Cada ficha indica el tiempo de caminata y el aeropuerto más cercano."""),
 id=("Air terjun adalah aliran air yang jatuh dari tempat tinggi. Di peta dan papan jalan Sumba, kata ini mendahului nama tempat, seperti Air Terjun Lapopu atau Air Terjun Tanggedu. Sebagian besar air terjun di pulau ini harus dicapai dengan berjalan kaki dan paling deras pada musim hujan.",
 """Lima air terjun yang memiliki halaman sendiri di situs ini menunjukkan betapa beragamnya. Lapopu di Wanokaka, Sumba Barat, dan Matayangu di Sumba Tengah adalah air terjun hutan yang dicapai dengan berjalan kaki; Matayangu menuntut trekking sungguhan menembus hutan. Waikelo Sawah, di antara Tambolaka dan Waikabubak, adalah sungai yang keluar dari gua, sekitar 1,5 km berjalan kaki dari jalan utama jika datang dengan angkutan umum. Di timur, Tanggedu bukan satu air terjun tinggi, melainkan rangkaian jeram dan kolam alami tempat sungai membelah ngarai batu kapur, dicapai dengan berjalan sekitar 3 km melintasi sabana atau naik ojek. Waimarang adalah air terjun kecil yang mengisi kolam alami luas berair jernih kehijauan, di pedalaman Melolo.
Musim mengubah segalanya. Pada musim hujan, kira-kira Desember sampai Maret, air terjun paling deras dan perbukitan menghijau, tetapi jalur hutan menjadi berlumpur dan licin serta jalan bisa terputus. Pada musim kemarau jalurnya lebih mudah.
Kenakan sepatu bersol kesat dan bawa air minum. Tidak ada penjaga, jadi bertanyalah kepada warga sebelum berenang. Untuk jalur panjang seperti Matayangu, yang tidak bertanda, sewalah pemandu setempat. Tiap halaman mencantumkan lama berjalan kaki dan bandara terdekat."""))

term("bukit", {"en": "Bukit (hill)", "es": "Bukit (colina)", "id": "Bukit"}, r"\bbukit\b", ["sumba-sunsets-sunrises", "wairinding-hill", "bukit-persaudaraan", "tanau-hill", "lendongara-hill"], ["kbbi_bukit"], pron="BOO-kit", nolink=("id",),
 en=("Bukit is the Indonesian word for hill: ground higher than its surroundings but lower than a mountain. In Sumba the word names the island's best-known viewpoints, such as Bukit Wairinding, Bukit Persaudaraan and Bukit Tanau near Waingapu and Bukit Lendongara near Tambolaka. They are places for sunrise and sunset.",
 """The Indonesian dictionary KBBI defines bukit as a mound of earth higher than the land around it and lower than a mountain. On signs the word comes first, so Wairinding Hill is Bukit Wairinding, and a driver will understand the Indonesian name sooner than the English one.
East Sumba's hills are savanna: rounded, grassy and almost treeless, gold in the dry season and green for a few months after the rains. Wairinding is the classic, about 30 to 45 minutes west of Waingapu airport. Bukit Persaudaraan is Waingapu's easy sunset viewpoint on the edge of town, and a bemo heading east on Jalan Ahmad Yani can drop you near the turn-off. Bukit Tanau, about 15 km from Waingapu, is a savanna hill for sunrise, with no public transport. In the west, Bukit Lendongara is Tambolaka's sunset hill.
None of these is a long hike. At Bukit Persaudaraan, depending on where you are dropped, the last part is an uphill walk of up to about 30 minutes on grass and rough track; at Wairinding there is nothing to do except walk up, sit and watch the light change.
There is no shade, so the middle of the day is the wrong time. Arrive before sunrise or well before sunset and bring water. Plan the drive back: roads are unlit, and animals sleep on the warm asphalt at night."""),
 es=("Bukit es la palabra indonesia para colina: un terreno más alto que lo que lo rodea, pero más bajo que una montaña. En Sumba da nombre a los miradores más conocidos de la isla, como Bukit Wairinding, Bukit Persaudaraan y Bukit Tanau, cerca de Waingapu, y Bukit Lendongara, cerca de Tambolaka. Son lugares para ver amanecer y atardecer.",
 """El diccionario indonesio KBBI define bukit como una elevación de tierra más alta que el terreno que la rodea y más baja que una montaña. En las señales la palabra va primero, de modo que la colina de Wairinding es Bukit Wairinding, y un conductor entenderá antes el nombre indonesio que el traducido.
Las colinas de Sumba Oriental son de sabana: redondeadas, cubiertas de hierba y casi sin árboles, doradas en la estación seca y verdes unos meses después de las lluvias. Wairinding es la clásica, a unos 30 o 45 minutos al oeste del aeropuerto de Waingapu. Bukit Persaudaraan es el mirador fácil para el atardecer, a las afueras de Waingapu, y un bemo que vaya hacia el este por Jalan Ahmad Yani puede parar cerca del desvío. Bukit Tanau, a unos 15 kilómetros de Waingapu, es una colina de sabana para ver amanecer, sin transporte público. En el oeste, Bukit Lendongara es la colina del atardecer de Tambolaka.
Ninguna exige una caminata larga. En Bukit Persaudaraan, según dónde lo dejen a uno, el último tramo es una subida de hasta media hora por hierba y pista irregular; en Wairinding no hay nada que hacer salvo subir, sentarse y ver cómo cambia la luz.
No hay sombra, de modo que el mediodía es mala hora. Conviene llegar antes del amanecer o con tiempo antes de la puesta de sol y llevar agua. Hay que prever la vuelta: las carreteras no tienen alumbrado y de noche los animales duermen sobre el asfalto caliente."""),
 id=("Bukit adalah tumpukan tanah yang lebih tinggi daripada tempat sekelilingnya dan lebih rendah daripada gunung. Di Sumba, kata ini melekat pada titik pandang paling dikenal di pulau ini, seperti Bukit Wairinding, Bukit Persaudaraan, dan Bukit Tanau di dekat Waingapu serta Bukit Lendongara di dekat Tambolaka. Semuanya tempat menikmati matahari terbit dan terbenam.",
 """KBBI mendefinisikan bukit sebagai tumpukan tanah yang lebih tinggi daripada tempat sekelilingnya, lebih rendah daripada gunung. Bagi pengunjung dari luar negeri, sopir akan lebih cepat memahami nama Bukit Wairinding daripada terjemahannya.
Perbukitan Sumba Timur adalah sabana: membulat, berumput, dan nyaris tanpa pohon, keemasan pada musim kemarau dan hijau selama beberapa bulan setelah hujan. Wairinding adalah yang paling terkenal, sekitar 30 sampai 45 menit di barat Bandara Waingapu. Bukit Persaudaraan adalah titik senja yang mudah dicapai di pinggir Waingapu, dan bemo ke arah timur di Jalan Ahmad Yani bisa menurunkan penumpang di dekat simpangnya. Bukit Tanau, sekitar 15 km dari Waingapu, adalah bukit sabana untuk matahari terbit, tanpa angkutan umum. Di barat, Bukit Lendongara adalah bukit senja di dekat Tambolaka.
Tidak satu pun menuntut pendakian panjang. Di Bukit Persaudaraan, bergantung pada tempat Anda diturunkan, ruas terakhir adalah jalan menanjak hingga sekitar 30 menit di atas rumput dan jalur kasar; di Wairinding tidak ada yang perlu dilakukan selain naik, duduk, dan menyaksikan cahaya berubah.
Tidak ada naungan, jadi tengah hari adalah waktu yang salah. Datanglah sebelum matahari terbit atau jauh sebelum terbenam dan bawa air minum. Rencanakan perjalanan pulang: jalan tidak berlampu dan pada malam hari ternak tidur di atas aspal yang hangat."""))

term("danau", {"en": "Danau (lake)", "es": "Danau (lago)", "id": "Danau"}, r"\bdanau\b", ["weekuri-lagoon", "laipori-lake", "beaches-lagoons-waterfalls"], ["kbbi_danau"], pron="DAH-now", nolink=("id",),
 en=("Danau is the Indonesian word for lake: a large body of water surrounded by land. In Sumba the word is used both for true lakes, such as Danau Laipori east of Waingapu, and for Weekuri, the saltwater lagoon in the south-west that Indonesians call Danau Weekuri.",
 """The Indonesian dictionary KBBI defines danau as a very wide expanse of standing water surrounded by land, and gives telaga and tasik as synonyms. The two that travellers visit in Sumba are very different from each other.
Danau Weekuri, in Kodi Utara, Southwest Sumba, is the famous one. In English it is usually called Weekuri Lagoon, and that is the more exact term: it is a saltwater lagoon filled by seawater seeping through the coral rock that separates it from the open ocean. It is roughly 40 to 60 km from Tambolaka airport, about 1.5 to 2 hours by car, and visitors were usually asked for around IDR 15,000 to 20,000 per person in 2025-2026. Go in the dry season, in the morning on a weekday, and wear water shoes on the slippery rocks.
Danau Laipori, also called Danau Cemara, is a small lake in Palakahembi village, Pandawai district, about 20 km by road east of Waingapu. It is ringed by cemara trees and lontar palms, unusual shade in the dry east. The last 2 km from the main road are unpaved and rocky, there are no facilities and no published fee, and swimming is not recommended without local advice.
If you search a map in Indonesian, type danau; in English, try both lake and lagoon."""),
 es=("Danau es la palabra indonesia para lago: una gran masa de agua rodeada de tierra. En Sumba se usa tanto para lagos propiamente dichos, como el Danau Laipori, al este de Waingapu, como para Weekuri, la laguna de agua salada del suroeste que los indonesios llaman Danau Weekuri.",
 """El diccionario indonesio KBBI define danau como una extensión muy amplia de agua estancada rodeada de tierra, y da telaga y tasik como sinónimos. Los dos que visitan los viajeros en Sumba se parecen muy poco entre sí.
El Danau Weekuri, en Kodi Utara, Sumba Suroccidental, es el famoso. En español se le suele llamar laguna de Weekuri, y es el término más exacto: es una laguna de agua salada que se llena con el agua del mar que se filtra por la roca coralina que la separa del océano abierto. Está a entre 40 y 60 kilómetros del aeropuerto de Tambolaka, a una hora y media o dos horas en coche, y en 2025-2026 a los visitantes se les solían pedir entre 15.000 y 20.000 rupias por persona. Conviene ir en la estación seca, por la mañana y en día laborable, y llevar escarpines para las rocas resbaladizas.
El Danau Laipori, llamado también Danau Cemara, es un pequeño lago en la aldea de Palakahembi, distrito de Pandawai, a unos 20 kilómetros por carretera al este de Waingapu. Lo rodean árboles cemara y palmeras lontar, una sombra poco habitual en el este seco. Los últimos 2 kilómetros desde la carretera principal son de pista pedregosa sin asfaltar, no hay servicios ni tarifa publicada, y no se recomienda bañarse sin consultar antes a la gente del lugar.
Quien busque en un mapa en indonesio debe escribir danau; en español o en inglés, conviene probar tanto con lago como con laguna."""),
 id=("Danau adalah genangan air yang amat luas dan dikelilingi daratan. Di Sumba kata ini dipakai baik untuk danau sesungguhnya, seperti Danau Laipori di timur Waingapu, maupun untuk Weekuri, laguna air asin di barat daya yang dikenal sebagai Danau Weekuri.",
 """KBBI mendefinisikan danau sebagai genangan air yang amat luas, dikelilingi daratan, dengan telaga dan tasik sebagai padanannya. Dua danau yang dikunjungi pelancong di Sumba sangat berbeda satu sama lain.
Danau Weekuri, di Kodi Utara, Sumba Barat Daya, adalah yang terkenal. Dalam bahasa Inggris tempat ini biasa disebut Weekuri Lagoon, dan itu istilah yang lebih tepat: Weekuri adalah laguna air asin yang terisi air laut yang merembes lewat batu karang pemisahnya dari laut lepas. Jaraknya sekitar 40 sampai 60 km dari Bandara Tambolaka, kira-kira 1,5 sampai 2 jam bermobil, dan pada 2025-2026 pengunjung biasanya diminta sekitar Rp 15.000 sampai Rp 20.000 per orang. Datanglah pada musim kemarau, pagi hari pada hari kerja, dan kenakan sepatu air karena batunya licin.
Danau Laipori, juga disebut Danau Cemara, adalah danau kecil di Desa Palakahembi, Kecamatan Pandawai, sekitar 20 km lewat jalan di timur Waingapu. Danau ini dikelilingi pohon cemara dan lontar, naungan yang jarang ada di timur yang kering. Dua kilometer terakhir dari jalan utama belum beraspal dan berbatu, tidak ada fasilitas maupun tarif resmi, dan berenang tidak disarankan tanpa bertanya dulu kepada warga.
Jika mencari di peta dalam bahasa Inggris, cobalah kata lake dan lagoon."""))

